INSERT INTO `articles` (`id`, `language`, `title`, `category`, `slug`, `short`, `content`, `date`, `cover_image`, `author`, `visibility`) VALUES
(1, 'az', 'Bu gün Azərbaycanda ilk tədrisedici, programlaşdırma üzrə məsələlərini test edən portal acıldı.', 5, 'bu-gun-azerbaycanda-ilk-tedrisedici-programlashdirma-uzre-meselelerini-test-eden-portal-acildi', '<p>Bu gün Azərbaycanda ilk tədrisedici, programlaşdırma üzrə məsələlərini test edən portal acıldı. Bu portal şagirdlərə və tələbələrə olimpiyada yarışlarına hazırlaşmağa kömək etmək məqsədi ilə yaradılıb.</p>', '<span class=\"text-justify\"><p>Bu gün Azərbaycanda ilk tədrisedici, programlaşdırma üzrə məsələlərini test edən portal acıldı. Bu portal şagirdlərə və tələbələrə olimpiyada yarışlarına hazırlaşmağa kömək etmək məqsədi ilə yaradılıb.</p>\n\n\n<p>Test sisteminin beta versiyası artıq mövcuddur Məsələlərin siyahısı tez zamanda yenilənəcək.</p>\n\n<p>Nəzərə çatdırımaq istəyirik ki, bu resurs üç dil dəstəkləyir: rus, inglis və azərbaycan.</p>\n\n<p>Layıhənın qurucuları Lomonosov adına MSU-nun Bakı filialının 4-cü kurs tələbəsi Vəliyev Əli, Lomonosov adına MSU-nun Bakı filialının 1-ci kurs magistrı Proskuryakov Aleksandr. Yaradılan dizayn və dəstəyə görə <a href=\"http://bitep.net\">Bitep</a> kompaniyasına va <a href=\"http://qformat.net\">Qformat</a>&nbsp; intellektual klubuna təşəkkürümüzü bildiririk. Həmçinin, Lomonosov adına MSU-nun Bakı filialının tələbələrinə Kamran Kazımi və İsayeva Səbinəyə interfeys tərcüməsinə görə təşəkkürümüzü bildiririk.</p>\n\n<p>Məsələlərin&nbsp; və dərslərin müzakirəsı <a href=\"http://qformat.net/blog/ocode/\">Qformat</a> intellektual klubunun veb-saytında aparılacaq.</p>\n\n<p>Programlaşdırma ilə məşgul olmaq istəyən hər kəsə uğurlar diləyirik. Biz çox güman edirik ki, bizim layihə sizin üçün çox faydalı olacaq.</p>\n\n<p>Bundan əlavə bizi <a href=\"http://www.facebook.com/studyprog\">Facebook</a>,&nbsp;<a href=\"http://vk.com/studyprog\">VK</a> və <a href=\"https://twitter.com/StudyProg\">Twitter</a>-də izləyə bilərsiniz.&nbsp;</p>\n</span>', '2013-09-14 06:00:00', 0, 1, 1),
(2, 'az', 'Bu gün Qafqaz Universitetində ACM-ICPC Azerbaijan subregional başa çatdı', 106, 'bu-gun-qafqaz-universitetinde-acm-icpc-azerbaijan-subregional-basha-chatdi', '<span class=\"text-justify\"><p>Bu gün noyabirin 3-cü 2013 il, Qafqaz Universitetində ACM-ICPC IX Azerbaijan Subregional Contest başa çatdı. Contestdə Azərbaycan universitetlərindən 45 komanda iştirak etmişdir. Rəsmi nəticələri <a href=\"http://neerc.ifmo.ru/subregions/standings/azerbaijan-2013.html\">burada</a> baxa bilərsiniz. Növbəti mərhələ Gurcüstanın paytaxtı Tbilisi şəhərində 30 noyabr - 1 dekabr tarixində keciriləcək. Azərbaycan komandalarına ugurlar dinləyirik!</p>\n</span>', '<span class=\"text-justify\"><p>Bu gün noyabirin 3-cü 2013 il, Qafqaz Universitetində ACM-ICPC IX Azerbaijan Subregional Contest başa çatdı. Contestdə Azərbaycan universitetlərindən 45 komanda iştirak etmişdir. Rəsmi nəticələri <a href=\"http://neerc.ifmo.ru/subregions/standings/azerbaijan-2013.html\">burada</a> baxa bilərsiniz. Növbəti mərhələ Gurcüstanın paytaxtı Tbilisi şəhərində 30 noyabr - 1 dekabr tarixində keciriləcək. Azərbaycan komandalarına ugurlar dinləyirik!</p>\n</span>', '2013-11-03 13:39:52', 0, 1, 1),
(3, 'az', 'Milli Net 2013-də saytların qeydiyyatı başa çatıb', 106, 'milli-net-2013-de-saytlarin-qeydiyyati-basha-chatib', '<span class=\"text-justify\"><p>Milli Net Təşkilat Komitəsi bildirir ki, noyabrın 23-ü saat 24.00-da Milli Net-də saytların qeydiyyatı başa çatıb.</p>\n<p>Milli Net Təşkilat Komitəsi bildirir ki, noyabrın 23-ü saat 24.00-da &nbsp;Milli Net-də saytların qeydiyyatı başa çatıb. Bu il Milli İnternet Mükafatına 14 Nominasiya üzrə &nbsp;401 sayt təqdim edilib və hələlik 307 sayt Müsabiqəyə qəbul olunub.</p></span>', '<span class=\"text-justify\"><p>Milli Net Təşkilat Komitəsi bildirir ki, noyabrın 23-ü saat 24.00-da Milli Net-də saytların qeydiyyatı başa çatıb.</p>\n\n\n<p>Milli Net Təşkilat Komitəsi bildirir ki, noyabrın 23-ü saat 24.00-da &nbsp;Milli Net-də saytların qeydiyyatı başa çatıb. Bu il Milli İnternet Mükafatına 14 Nominasiya üzrə &nbsp;401 sayt təqdim edilib və hələlik 307 sayt Müsabiqəyə qəbul olunub.</p>\n\n<p>Saytların qeydiyyat müddəti bitdikdən sonra istifadəçilər yalnız Müsabiqəyə qəbul edilən saytlara öz şərhlərini və rəylərini yazmaq üçün qeydiyyatdan keçə bilərlər.</p>\n\n<p>Bu müddətədək saytlarını qeydiyyatdan keçirib təqdim edənlər, lakin müxtəlif problemlər səbəbindən Milli Net TK tərəfindən &nbsp;Müsabiqəyə buraxılmayanlar &nbsp;1-ci səsvermə başa çatanadək yenidən müraciət edə bilərlər.</p>\n\n<p>Hazırda Milli Net-ə qəbul edilən saytların 1-ci səsvermə prosesi başlayıb və dekabrın 2-si başa çatacaq. 1-ci səsvermənin yekunu olaraq Milli Net –in Nominantları seçiləcək və &nbsp;Nominantlar arasından 2-ci səsvermə nəticəsində Milli İnternet Mükafatının qalibləri müəyyən olunacaq.</p>\n\n<p>2-ci səsvermə prosesi dekabr 3-ü başlayacaq və dekabrın 15- i yekunlaşacaq.</p>\n\n<p>Münsiflərin verdikləri qiymətlər və şərhlər yalnız Təqdimat mərasimindən sonra açıqlanacaq.</p>\n\n<p>Qaliblərin mükafatlandırılması ilə bağlı TƏQDİMAT mərasiminin &nbsp;dekabrın sonunda keçirilməsi nəzərdə tutulub.&nbsp;</p>\n\n<p>Hazırda Təşkilat Komitəsi qaliblərin mükafatlandırılmasına hazırlıq işləri görür.</p>\n\n<p>Müsabiqənin Baş sponsoru Azercell şirkətidir. &nbsp;RİTN və Delta Telecom şirkətləri də Milli İnternet Mükafatına &nbsp;dəstək verirlər.</p>\n\n<p>Daha geniş məlumat www.millinet.az &nbsp; &nbsp; saytında yerləşdirilib.</p>\n\n<p>Qeyd edək ki bizim gənc portalılımız da MilliNet müsabigəsində \"Elm və təhsil\" kateqoriyasında&nbsp;iştirak edir.</p></span>', '2013-11-25 11:40:49', 0, 1, 1),
(4, 'az', 'Analitik həlli olan məsələlərin test olunması.', 5, 'analitik-helli-olan-meselelerin-test-olunmasi', '<span class=\"text-justify\"><p>Veb-saytda analitik həlli olan məsələlərin həll olunması üçün daha rahat interfeysdən.</p>\n\n<p>Hal hazırda bu kategoriyada variyasiya hesablanmasının asan məsələləri var. Bu məsələlərin həlli <b>t</b> parametrdən asılı olan həqiqi funksiyadır. Həllivizi yoxlamaq üçün onu müvafiq sahəyə çap edin və \"Göndər\" düyməsini basın (bütün riyazi funksiyalari və əməliyyatları C dilinin qaydalarına uyğun yığın).</p>\n</span>', '<span class=\"text-justify\"><p>Veb-saytda analitik həlli olan məsələlərin həll olunması üçün daha rahat interfeysdən.</p>\n\n<p>Hal hazırda bu kategoriyada variyasiya hesablanmasının asan məsələləri var. Bu məsələlərin həlli <b>t</b> parametrdən asılı olan həqiqi funksiyadır. Həllivizi yoxlamaq üçün onu müvafiq sahəyə çap edin və \"Göndər\" düyməsini basın (bütün riyazi funksiyalari və əməliyyatları C dilinin qaydalarına uyğun yığın).</p>\n\n\n<p>Misal üçün <a href=\"http://studyprog.com/problem/show?id=57\">57</a>-ci məsələyə nəzər edək, onun həlli <b>t</b> funksiyasıdı. <b>t</b> sözünü müvafiq sahəyə yazanda <b>Hesablanıb</b> cavabını alırıq. İndi hesab edək ki məsələni səhv həll etmişik, misal üçün <b>t*t</b> funksiyası alındı. Yazanda görürük ki sistem <b>Cavab yalnışdı</b> cavabını qaytarır.</p>\n</span>', '2013-11-25 11:45:34', 0, 1, 1),
(5, 'az', 'AMEA-nın İnformasiya Texnologiyaları İnstitutunda keçirilmiş final mərhələsində qaliblər müəyyənləşdirilmişdir.', 106, 'amea-nin-informasiya-texnologiyalari-institutunda-kechirilmish-final-merhelesinde-qalibler-mueyyenleshdirilmishdir', '<span class=\"text-justify\"><p>Rabitə və Yüksək Texnologiyalar Nazirliyinin, Heydər Əliyev Fondunun, Təhsil Nazirliyinin və AMEA-nın İnformasiya Texnologiyaları İnstitutunun birgə təşkilatçılığı ilə 17 May - Dünya Telekommunikasiya və İnformasiya Cəmiyyəti Gününə həsr olunan “Ali məktəb tələbələri arasında informatika üzrə Ümumrespublika Olimpiadası” 2014-cü ildə növbəti 9-cu dəfə keçirilmişdir. Olimpiadanın 13 aprel 2104-cü il tarixində keçirilmiş ilk mərhələsində respublikanın 8 ali təhsil müəssisəsindən 49 komanda iştirak etmişdir. Respublikanın 8 ali təhsil müəssisəsindən 28 komanda ikinci (final) mərhələsinə vəsiqə qazanmışdır. 26 aprel 2014-cü il tarixində AMEA-nın İnformasiya Texnologiyaları İnstitutunda keçirilmiş final mərhələsində qaliblər müəyyənləşdirilmişdir.</p>\n</span>', '<span class=\"text-justify\"><p>Rabitə və Yüksək Texnologiyalar Nazirliyinin, Heydər Əliyev Fondunun, Təhsil Nazirliyinin və AMEA-nın İnformasiya Texnologiyaları İnstitutunun birgə təşkilatçılığı ilə 17 May - Dünya Telekommunikasiya və İnformasiya Cəmiyyəti Gününə həsr olunan “Ali məktəb tələbələri arasında informatika üzrə Ümumrespublika Olimpiadası” 2014-cü ildə növbəti 9-cu dəfə keçirilmişdir. Olimpiadanın 13 aprel 2104-cü il tarixində keçirilmiş ilk mərhələsində respublikanın 8 ali təhsil müəssisəsindən 49 komanda iştirak etmişdir. Respublikanın 8 ali təhsil müəssisəsindən 28 komanda ikinci (final) mərhələsinə vəsiqə qazanmışdır. 26 aprel 2014-cü il tarixində AMEA-nın İnformasiya Texnologiyaları İnstitutunda keçirilmiş final mərhələsində qaliblər müəyyənləşdirilmişdir.</p>\n\n\n<p><b>1-ci yer</b></p>\n\n<p>Qafqaz Universitetinin “Qafqaz Programmers” komandası</p>\n\n<p><b>2-ci yer</b></p>\n\n<p>M.V. Lomonosov adına Moskva Dövlət Universitetinin Bakı filialının “MSU Programmers” komandası</p>\n\n<p><b>3-cü yer</b></p>\n\n<p>Qafqaz Universitetinin “Qafqaz U4” komandası</p>\n\n<p>Olimpiada qalibləri 17 may - Dünya Telekommunikasiya və İnformasiya Cəmiyyəti Gününə həsr olunan tədbirdə “HP” şirkətinin qiymətli hədiyyələri ilə mükafatlandırılacaqlar.</p>\n</span>', '2014-04-28 12:53:42', 0, 1, 1),
(6, 'az', 'Tələbələr arasında beynəlxalq ACM ICPC proqramlaşdırma yarışının ölkə mərhələsi keçirilir', 106, 'telebeler-arasinda-beynelxalq-acm-icpc-proqramlashdirma-yarishinin-olke-merhelesi-kechirilir', '<span class=\"text-justify\"><p>Universitet Tələbələrinin 39-cu ACM ICPC (International Collegiate Programming Contest) Beynəlxalq Proqramlaşdırma Müsabiqəsinin ¼ final və ya ölkə mərhələsi 9 noyabr 2014-cü ildə keçiriləcək.</p>\n\n\n<p>Saat 10.00-da Qafqaz Universitetində müsabiqənin rəsmi açılışı olacaq. Tədbirin təşkilatçıları Qafqaz Universiteti, Bakı Dövlət Universiteti, Proqramlaşdırma Müsabiqələri İştirakçılarının Milli Assosiasiyası, IEEE Azərbaycan bölməsi və Azərbaycan ACM Bölməsidir. Xatırladaq ki, ACM ICPC müsabiqəsinin Azərbaycan üzrə regional direktoru Bakı Dövlət Universitetinin dosenti, fizika-riyaziyyat elmləri namizədi Ramin Mahmudzadə, münsiflər heyətinin sədri isə Qafqaz Universitetinin baş müəllimi Etibar Seyidzadədir.</p>\n</span>', '<span class=\"text-justify\"><p>Universitet Tələbələrinin 39-cu ACM ICPC (International Collegiate Programming Contest) Beynəlxalq Proqramlaşdırma Müsabiqəsinin ¼ final və ya ölkə mərhələsi 9 noyabr 2014-cü ildə keçiriləcək.</p>\n\n\n<p>Saat 10.00-da Qafqaz Universitetində müsabiqənin rəsmi açılışı olacaq. Tədbirin təşkilatçıları Qafqaz Universiteti, Bakı Dövlət Universiteti, Proqramlaşdırma Müsabiqələri İştirakçılarının Milli Assosiasiyası, IEEE Azərbaycan bölməsi və Azərbaycan ACM Bölməsidir. Xatırladaq ki, ACM ICPC müsabiqəsinin Azərbaycan üzrə regional direktoru Bakı Dövlət Universitetinin dosenti, fizika-riyaziyyat elmləri namizədi Ramin Mahmudzadə, münsiflər heyətinin sədri isə Qafqaz Universitetinin baş müəllimi Etibar Seyidzadədir.</p>\n\n<p>Müsabiqədə müxtəlif universitetlərin komandaları iştirak edir, qalib komandalar regional yarımfinala vəsiqə qazanır. İştirak edən hər komanda 3 nəfər bakalavr və ya magistratura səviyyəsində təhsil alan tələbədən ibarət olur. Komandalar 5 saat ərzində verilən məsələləri həll etməyə çaılışır. Beynəlxalq İnformatika Olimpiadasından fərqli olaraq burada bir məsələnin həlli ancaq bütün testləri uğurla keçdikdə düzgün hesab olunur. Komandalara 9-11 alqoritmik məsələnin şərti verilir və müsabiqə zamanı iştirakçılar məsələlərin həllini C, C++, C#, Cava (Java), Paskal (Pascal) proqramlaşdırma dillərindən birində yazıb avtomatik qiymətləndirmə sisteminə göndərirlər. Məsələlərin həlli bu sistem vasitəsilə yoxlanır və komandaya uyğun ballar verilir. Müsabiqənin şərtləri barədə daha ətraflı məlumatı <a href=\"http://icpc.baylor.edu\" target=\"_blank\">http://icpc.baylor.edu</a> veb-saytından əldə etmək olar.</p>\n</span>', '2014-11-08 12:02:35', 0, 1, 1),
(7, 'az', '\"ACM ICPC X Azerbaijan Subregional Championship\"-in nəticələri', 106, 'acm-icpc-x-azerbaijan-subregional-championship-in-neticeleri', '<span class=\"text-justify\"><p>Qafqaz Universitetində “39-cu ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (X Azərbaycan Çempionluğu) keçirildi.</p>\n<p>Qafqaz Universiteti, Bakı Dövlət Universiteti, NAPCAR, IEEE Computer Society Azərbaycan bölməsi, IEEE Telecommunication Society Azərbaycan bölməsi, ACM Azərbaycan bölməsinin təşkilatı dəstəyi ilə “39-cu ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (X Azərbaycan Çempionluğu) 9 noyabr 2014-cü il tarixində Qafqaz Universitetində keçirildi.</p>\n</span>', '<span class=\"text-justify\">Qafqaz Universitetində “39-cu ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (X Azərbaycan Çempionluğu) keçirildi.<br>\nQafqaz Universiteti, Bakı Dövlət Universiteti, NAPCAR, IEEE Computer Society Azərbaycan bölməsi, IEEE Telecommunication Society Azərbaycan bölməsi, ACM Azərbaycan bölməsinin təşkilatı dəstəyi ilə “39-cu ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (X Azərbaycan Çempionluğu) 9 noyabr 2014-cü il tarixində Qafqaz Universitetində keçirildi.<br>\nMüsabiqədə 14 universitetdən, o cümlədən 58 komanda (hər komandada 3 tələbə) və müsabiqədənkənar 3 məktəblilər komandası iştirak etdi.<br>\nQafqaz Universiteti – 10<br>\nMoskva Dövlət Universitetinin Bakı filialı – 8<br>\nBakı Dövlət Universiteti – 8<br>\nAzərbaycan Dövlət Neft Akademiyası – 6<br>\nAzərbaycan Milli Aviasiya Akademiyası – 6<br>\nADA Universiteti – 5<br>\nBakı Ali Neft Məktəbi - 3<br>\nAzərbaycan Texniki Universiteti – 3<br>\nXəzər Universiteti – 3<br>\nAzərbaycan Universiteti – 3<br>\nAzərbaycan Memarlıq və İnşaat Universiteti – 1<br>\nAzərbaycan Dövlət Pedaqoji Universiteti – 1<br>\nNaxçıvan Dövlət Universiteti – 1<br>\nOdlaryurdu Univerditeti - 1<br>\nMəktəblilər – 3 (müsabiqədən kənar)<br>\nkomanda ilə (hər komandada 3 nəfər) təmsil olunmuşlar.<br>\nKomandalara 5 saat ərzində 12 alqoritmik məsələni həll etmək tapşırığı verildi. Qiymətləndirmə e-olimp.com.ua/az saytında avtomatik test sistemi ilə aparıldı.<br>\nQafqaz Universitetinin Qafqaz U 1 komandası I; Qafqaz U 2 komandası II; Qafqaz U 3 və Qafqaz U 5 komandaları III, Moskva Dövlət Universitetinin Bakı filialının BakuMSU1 və BakuMSU8 komandaları III yerə layiq görüldülər.<br>\nQafqaz Universitetinin Qafqaz U 6, Qafqaz U 4, Azərbaycan Dövlət Neft Akademiyasının Az SOA 5, Bakı Dövlət Universitetinin Baku SU1, BakuSU 3, Baku SU 2, Moskva Dövlət Universitetinin Bakı flialının BakuMSU2, məktəblilərdən ibarət SHOOL1 və SHOOL2 komandaları III dərəcəli diplomla təltif olundular.<br>\nMüsabiqənin qalibləri 6-7 dekabr 2014-cü il tarixlərində Gürcüstan Respublikasının Tbilisi şəhərində keçiriləcək “39-cu ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti yarımfinal mərhələsində və Cənubi Qafqaz açıq çempionatında iştirak etmək üçün vəsiqə qazanmışlar.<br>\n<br>\n<a href=\"http://studyprog.com/pages/getPage?p=acm_azerbaijan2014\">Nəticələr</a><br>\n<br>\nI YER<br>\nQafqaz U 1 komandası<br>\nMəhəmməd Vəliyev, Elmi Əhmədov, Təbriz Hacıyev<br>\n<br>\nII YER<br>\nQafqaz U 2 komandası<br>\nRəşad Məmmədov, Qalib Sarayev, Eldar Həsənov<br>\n<br>\nIII YER<br>\nQafqaz U 3 komandası<br>\nNurlan Əliyev, Rövşən Hüseynov, Mahmud Allahverdiyev<br>\n<br>\nIII YER<br>\nBakuMSU1 komandası<br>\nAleksandr Proskuryakov, Əli Vəliyev, Səbuhi Əzimzadə<br>\n<br>\nIII YER<br>\nQafqaz U 5 komandası<br>\nƏləkbər Vəlizadə, Hidayət Soltanzadə, Orxan İsmayilov<br>\n<br>\nIII YER<br>\nBakuMSU8 komandası<br>\nQəzənfər Ağayev, Şahin Kazımov, Bahri Abdullaxan<br>\n<br>\nMənbə: Etibar Səidzadə, Facebookun National Association of Programming Contestants of Azerbaijan Republic grupu.</span>', '2014-11-11 15:09:05', 0, 1, 1),
(8, 'az', 'MDU-nun Bakı filialının magistrantlarının Studyprog layihəsi Milli Net 2014 mükafatında ən yaxşılar sırasına daxil olub', 5, 'mdu-nun-baki-filialinin-magistrantlarinin-studyprog-layihesi-milli-net-2014-mukafatinda-en-yaxshilar-sirasina-daxil-olub', '<span class=\"text-justify\"><p>Milli İnternet mükafatı 2014 - Milli Net 2014 qaliblərin mükafatlandırılma mərasimi dekabrın 19-da Bakı Biznes Mərkəzində olub. 6-ci sessiyasında mükafatı təqdimetmə mərasimində Azərbaycan İnternet Forumunun prezidenti Osman Gündüz Milli Net 2014 təşkilat komitəsi adından çıxış edib, Milli Net 2014 və müsabiqə çərçivəsində görülən işlər haqqında məlumat verib.</p>\n</span>', '<span class=\"text-justify\">Milli İnternet mükafatı 2014 - Milli Net 2014 qaliblərin mükafatlandırılma mərasimi dekabrın 19-da Bakı Biznes Mərkəzində olub. 6-ci sessiyasında mükafatı təqdimetmə mərasimində Azərbaycan İnternet Forumunun prezidenti Osman Gündüz Milli Net 2014 təşkilat komitəsi adından çıxış edib, Milli Net 2014 və müsabiqə çərçivəsində görülən işlər haqqında məlumat verib.<br>\nBildirilmişdir ki, 14 nominasiya üzrə 322 sayt təqdim edilib, onlardan 272-i müsabiqəyə buraxılıb. M.V.lomonosov adına MDU-nun Bakı Filialının magistrantları Əli Vəliyev və Aleksandr Proskuryakovun tərəfindən yaradılmış www.studyprog.com saytı Milli Net 2014 müsabiqəsində fəxri üçüncü yeri tutub.<br>\nQeyd edək ki, Studyprog - Azərbaycanda ilk riyaziyyat, proqramlaşdırma və digər müxtəlif bölmə üzrə avtomatik test sistemidir. Bu layihənin yaradılma məqsədi proqramlaşdırma tədrisində şagirdlərə və tələbələrə də kömək etməkdi. Layihə tədris materialları və ya istənilən materialı mənimsəmək arzusunda olanlara kömək edəcək, bu sahədə elmi bazası zənginləşdirilir.<br>\nSayt üç dildə - azərbaycan, rus və ingilis fəaliyyət göstərir. Bu sistem vasitəsilə Moskva Dövlət Universitetinin Bakı Filialının tələbələri arasında proqramlaşdırma üzrə çempionatı və optimallaşdırılması metodları fənn üzrə yoxlama keçirilmişdir. Hazırda sistemdə Azərbaycan məktəblilər və tələbələr arasında proqramlaşdırma üzrə olimpiadaların keçirilməsi üçün imkan var.</span>', '2014-12-19 17:31:08', 0, 1, 1),
(9, 'az', '\"Ali məktəb tələbələri arasında informatika üzrə ümumrespublika olimpiadası”nın final mərhələsi keçirilib', 106, 'ali-mekteb-telebeleri-arasinda-informatika-uzre-umumrespublika-olimpiadasi”nin-final-merhelesi-kechirilib', '<span class=\"text-justify\"><p class=\"sizeable\" style=\"text-align: justify;\">Mayın 2-də AMEA İnformasiya Texnologiyaları İnstitutunda 17 May - Ümumdünya Telekommunikasiya və İnformasiya Cəmiyyəti gününə həsr olunan “Ali məktəb tələbələri arasında informatika üzrə ümumrespublika olimpiadası”nın final mərhələsi keçirilib.</p>\n\n\n<p class=\"sizeable\" style=\"text-align: justify;\">2007-ci ildən ardıcıl olaraq keçirilən tədbirin təşkilatçıları <a class=\"sizeable\" href=\"http://www.heydar-aliyev-foundation.org/az\" target=\"_blank\">Heydər Əliyev Fondu</a>, AR <a class=\"sizeable\" href=\"http://www.mincom.gov.az/\" target=\"_blank\">Rabitə və Yüksək Texnologiyalar Nazirliyi</a>, AR <a class=\"sizeable\" href=\"http://edu.gov.az/view.php?lang=az&amp;menu=0\" target=\"_blank\">Təhsil Nazirliyi</a> və AMEA İnformasiya Texnologiyaları İnstitutudur.</p>\n</span>', '<span class=\"text-justify\"><p class=\"sizeable\" style=\"text-align: justify;\">Mayın 2-də AMEA İnformasiya Texnologiyaları İnstitutunda 17 May - Ümumdünya Telekommunikasiya və İnformasiya Cəmiyyəti gününə həsr olunan “Ali məktəb tələbələri arasında informatika üzrə ümumrespublika olimpiadası”nın final mərhələsi keçirilib.</p>\n\n\n<p class=\"sizeable\" style=\"text-align: justify;\">2007-ci ildən ardıcıl olaraq keçirilən tədbirin təşkilatçıları <a class=\"sizeable\" href=\"http://www.heydar-aliyev-foundation.org/az\" target=\"_blank\">Heydər Əliyev Fondu</a>, AR <a class=\"sizeable\" href=\"http://www.mincom.gov.az/\" target=\"_blank\">Rabitə və Yüksək Texnologiyalar Nazirliyi</a>, AR <a class=\"sizeable\" href=\"http://edu.gov.az/view.php?lang=az&amp;menu=0\" target=\"_blank\">Təhsil Nazirliyi</a> və AMEA İnformasiya Texnologiyaları İnstitutudur.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Olimpiadanın final mərhələsində respublikanın 12 ali təhsil müəssisəsindən (Bakı Dövlət Universiteti (BDU), Azərbaycan Dövlət Neft Akademiyası, Qafqaz Universiteti, Bakı Ali Neft Məktəbi, Azərbaycan Texniki Universiteti, Moskva Dövlət Universitetinin (MDU) Bakı filialı, Naxçıvan Dövlət Universiteti, Azərbaycan Respublikası Prezidenti yanında Dövlət İdarəçilik Akademiyası, Azərbaycan Universiteti, Azərbaycan Memarlıq və İnşaat Universiteti, Milli Aviasiya Akademiyası, ADA Universiteti) 12 komanda iştirak edib.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Öncə qonaqlar institutda yaradılmış innovativ şəraitlə yaxından tanış oldular, onlara institutun maddi-texniki bazası haqqında ətraflı məlumat verilib.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Sonra təşkilat komitəsinin üzvləri, final mərhələsində iştirak edən universitetlərin nümayəndələrinin iştirakı ilə olimpiadanın açılış mərasimi keçirilib. Tədbiri giriş nitqi ilə açan Rabitə və yüksək texnologiyalar nazirinin müavini <strong>Elmir Vəlizadə</strong> ölkəmizdə informasiya-kommunikasiya texnologiyaları (İKT) sahəsində yüksək ixtisaslı gənc mütəxəssislərə böyük ehtiyac olduğunu bildirib. Qeyd edib ki, İKT-nin dinamik inkişafı və geniş vüsət alması dünyada informasiya cəmiyyətinin formalaşması, bəşəriyyətin inkişafı üçün böyük imkanlar yaradır. “Azərbaycanın gələcəyi olan gənclər də informasiya cəmiyyətinin qurulmasında yaxından iştirak etməlidirlər”, - deyə bildirən E.Vəlizadənin sözlərinə görə, 10-cu dəfədir keçirilən olimpiadanın 10-cu dəfədir keçirilən olimpiadanın ilk mərhələsində respublikanın 16 ali təhsil müəssisəsindən 55 komanda iştirak etmiş, 12 komanda final mərhələsinə vəsiqə qazanmışdır.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Nazir müavini cari ilin mayın 17-də Cenevrədə Azərbaycanın Qızıl Tərəfdaşı olduğu Beynəlxalq Telekommunikasiya İttifaqının (BTİ) 150 illik yubileyinin və Azərbaycan rabitəsinin yaranmasının 134 illiyinin qeyd olunacağını əlamətdar hadisə kimi qiymətləndirib.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Sonra çıxış edən olimpiadanın Münsiflər Heyətinin sədri, BDU-nun dosenti, Azərbaycanda informatika üzrə olimpiadaların əsasını qoyan <strong>Ramin Mahmudzadə</strong> gənclərin İKT biliklərinin təkmilləşdirilməsi, informatika və proqramlaşdırma sahəsində istedadlı tələbələrin aşkara çıxarılması və onlara dəstək vermək baxımından olimpiadanın böyük əhəmiyyətə malik olduğunu diqqətə çatdırıb. Qeyd edib ki, başlıca hədəflərdən biri informatika fənni üzrə respublika olimpiadasının qaliblərini beynəlxalq yarışlara hazırlaşdırmaqla Azərbaycanın intellektual yarışlarda yüksək səviyyədə təmsil olunmasına şərait yaratmaqdır.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">AMEA-nın akademik-katibi, İnformasiya Texnologiyaları İnstitutunun direktoru, akademik Rasim Əliquliyev bu gün dünyada informasiya texnologiyaları üzrə yüksəkixtisaslı, böyük elmi-praktiki təcrübəyə malik, innovativ təfəkkürlü kadrların, xüsusən də, proqram mühəndislərinin hazırlanmasına böyük tələbatın olduğunu bildirib. Ölkəmizdə də elm və təhsilin inkişafına ölkə rəhbərliyi tərəfindən daim diqqət və qayğı göstərildiyini söyləyən alim Rabitə və Yüksək Texnologiyalar Nazirliyinin xidmətləri sayəsində son 10 ildə Azərbaycanda İKT sahəsində yüksək nailiyyətlərin əldə olunduğunu dilə gətirib. Azərbaycanda qurulmaqda olan biliklər cəmiyyətinin əsas lokomotivinin proqram mühəndisliyi olduğunu söyləyən R.Əliquliyev bu sahənin AMEA rəhbərliyinin daim diqqət mərkəzində olan sahələrdən biri olduğunu vurğulayıb.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">İKT sahəsində innovasiyaların daha sürətlə vüsət almasında gənc kadrların rolundan danışan akademik bu sahədə yeni imkanların meydana gəlməsi və innovasiyaların geniş tətbiqi prosesinə innovativ təfəkkürə malik gənclərin böyük töhfə verdiyini vurğulayıb. Bu kimi tədbirlərin keçirilməsinin İKT üzrə innovativ təfəkkürə malik istedadlı gənclərin seçilməsi və onların ölkəmizdə bu sahə ilə bağlı həyata keçirilən layihələrə cəlb edilməsinə, ölkəmizin beynəlxalq yarışlarda layiqincə təmsil edilməsinə imkan yaratdığını önə çəkib.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Sonra olimpiada onlayn rejimdə, www.e-olimp.com saytı vasitəsilə keçirilib. Yarış zamanı hər komandaya 5 saat ərzində 9 məsələni həll etmək tapşırığı verilib.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Sonda ilk 4 yerə layiq görülmüş komandaların adları açıqlandı. Final mərhələsinin nəticələrinə görə, Qafqaz Universitetinin “Qafqaz Programmers” komandası 1-ci, Azərbaycan Texniki Universitetinin “AzTU1” və ADA Universitetinin “ADA U4” komandaları 2-ci, Milli Aviasiya Akademiyasının “NAA50”, Azərbaycan Dövlət Neft Akademiyasının ADNA1 və Bakı Ali Neft Məktəbinin BHOS1 komandaları isə 3-cü yerə layiq görülüblər.</p>\n\n<p class=\"sizeable\" style=\"text-align: justify;\">Qaliblərə mükafatlar 14 may 2014-cü il tarixdə AMEA İnformasiya Texnologiyaları İnstitutunda keçiriləcək 17 May - İnformasiya Cəmiyyəti Gününə həsr olunmuş tədbirdə təqdim olunacaq.</p>\n</span>', '2015-05-04 17:55:48', 0, 1, 1),
(10, 'az', '2019-2020-ci illərdə Beynəlxalq İnformatika Olimpiadası Azərbaycanda və Sinqapurda keçiriləcək', 106, '2019-2020-ci-illerde-beynelxalq-informatika-olimpiadasi-azerbaycanda-ve-sinqapurda-kechirilecek', '<span class=\"text-justify\"><p>2019-2020-ci illərdə Beynəlxalq İnformatika Olimpiadası Azərbaycanda və Sinqapurda keçiriləcək. Bu barədə “Kazinform” agentliyinə Olimpiadanın prezidenti Krassimir Manev bildirib: «Bu gün idarə heyətinin iclasında gələcək olimpiadaların keçiriləcək yerlərin adları açıqlanıb. 2019-cu ildə keçiriləcək Beynəlxalq İnformatika Olimpiadasını Azərbaycan qəbul edəcək. 2020-ci ildə isə Olimpadaya Sinqapur ev sahiblik edəcək».</p>\n</span>', '<span class=\"text-justify\"><p>2019-2020-ci illərdə Beynəlxalq İnformatika Olimpiadası Azərbaycanda və Sinqapurda keçiriləcək. Bu barədə “Kazinform” agentliyinə Olimpiadanın prezidenti Krassimir Manev bildirib: «Bu gün idarə heyətinin iclasında gələcək olimpiadaların keçiriləcək yerlərin adları açıqlanıb. 2019-cu ildə keçiriləcək Beynəlxalq İnformatika Olimpiadasını Azərbaycan qəbul edəcək. 2020-ci ildə isə Olimpadaya Sinqapur ev sahiblik edəcək».</p>\n\n\n<p>Xatırladaq ki, bu il Qazaxıstan ilk dəfə Beynəlxalq İnformatika Olimpiadasını qəbul edib. Tədbirdə 83 ölkədən 630 nümayəndə iştirak edib. Yarışda Güney Koreyadan Ci Xak Yun 600 mümkün baldan 600 bal yığıb. Qazaxıstan yığması 3 gümüş və 1 bürünc medal qazanıb.</p>\n\n<p>2016-cı ildə olimpiada Kazanda, 2017-ci ildə İranda, 2018-ci ildə Yaponiyada keçiriləcək.</p>\n</span>', '2015-08-08 08:01:46', 0, 1, 1),
(11, 'az', '11-ci ACM Azərbaycan Subregional 2015 keçirildi', 106, '11-ci-acm-azerbaycan-subregional-2015-kechirildi', '<span class=\"text-justify\"><p style=\"margin: 0px 0px 6px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Qafqaz Universitetində “40-cı ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (XI Azərbaycan Çempionluğu) keçirilib.</p>\n\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Qafqaz Universiteti, Bakı Dövlət Universiteti, ADA Universiteti, NAPCAR, IEEE Computer Society Azərbaycan Bölməsi, ACM Azərbaycan bölməsinin təşkilatı dəstəyi ilə “40-cı ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (XI Azərbaycan Çempionluğu) 24 oktyabr 2015-ci il tarixində Qafqaz Universitetində keçirilib. Müsabiqədə 15 universitetdən 62 komanda qeydiyyatdan keçib, 55 komanda iştirak edib:</p>\n</span>', '<span class=\"text-justify\"><p style=\"margin: 0px 0px 6px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Qafqaz Universitetində “40-cı ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (XI Azərbaycan Çempionluğu) keçirilib.</p>\n\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Qafqaz Universiteti, Bakı Dövlət Universiteti, ADA Universiteti, NAPCAR, IEEE Computer Society Azərbaycan Bölməsi, ACM Azərbaycan bölməsinin təşkilatı dəstəyi ilə “40-cı ACM ICPC Universitet Tələbələrinin Proqramlaşdırma üzrə Beynəlxalq” müsabiqəsinin növbəti 1/4 final mərhələsi (XI Azərbaycan Çempionluğu) 24 oktyabr 2015-ci il tarixində Qafqaz Universitetində keçirilib. Müsabiqədə 15 universitetdən 62 komanda qeydiyyatdan keçib, 55 komanda iştirak edib:</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">ADA Universiteti – 7 komanda<br>\nAzərbaycan Dövlət Aqrar Universiteti – 1 komanda<br>\nAzərbaycan Dövlət Neft və Sənaye Universiteti – 3 komanda<br>\nAzərbaycan Dövlət Pedaqoji Universiteti – 1 komanda<br>\nAzərbaycan Memarlıq və İnşaat Universiteti – 1 komanda<br>\nAzərbaycan Texniki Universiteti – 1 komanda<br>\nAzərbaycan Universiteti – 6 komanda<br>\nBakı Ali Neft Məktəbi - 4 komanda<br>\nBakı Dövlət Universiteti – 10 komanda<br>\nM.Lomonosov adına Moskva Dövlət Universitetinin Bakı filialı – 4 komanda<br>\nMilli Aviasiya Akademiyası – 6 komanda<br>\nNaxçıvan Dövlət Universiteti – 1 komanda<br>\nQafqaz Universiteti – 6 komanda<br>\nXəzər Universiteti – 4 komanda</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Komandalara 5 saat ərzində 12 alqoritmik məsələni C, C++, Java proqramlaşdırma dillərində həll etmək tapşırığı verilib. Qiymətləndirmə PCMS2 online avtomatik test sistemi ilə aparılıb.</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Müsabiqənin nəticələri:</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\"><a href=\"https://www.facebook.com/l.php?u=https%3A%2F%2Fneerc.ifmo.ru%2Finformation%2Fstandings-azb.html&amp;h=JAQHQKXliAQGrlYQatoPUnQpSYTc6OLnsAf0lqHvkkOHu1w&amp;enc=AZOrnYY24I5Yna1Q_QLa3fg3fizrwQcrW7nWUUrmIWvuwL-VTmr-qZEv5mK54Z-B9FmbKYTTf4QyQBkxEmlg91U8KDKzXH11x0kJMHB9FYuI4nMykHoBsgf1t73woTbRDv6OMU9QAiTemxnpYvojtk_RXDgWaltXzGYU5PHceGpeolKrbntpku6_bqOrwwhqZ4x5dPcUgFnyIkr002KUeEf_&amp;s=1\" rel=\"nofollow\" style=\"color: rgb(59, 89, 152); cursor: pointer; text-decoration: none;\" target=\"_blank\">https://neerc.ifmo.ru/information/standings-azb.html</a></p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">I YER<br>\nQafqaz University 2 (Mammadov, Sarayev, Allahverdiyev)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">II YER<br>\nQafqaz University 1 (Valiyev, Ahmadov, Hajiyev)<br>\nQafqaz University 3 (Kerimov, Huseynov, Hajili)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">III YER<br>\nBaku Branch of Moscow State University 1 (Yahyayev, Veliyev, Kazimi)<br>\nAzerbaijan Technical University (Mammadzade, Rehimova, Abdullayev)<br>\nQafqaz University 5 (Hasanov, Akhundov, Klyestov)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">II DƏRƏCƏLİ DİPLOM<br>\nBaku State University 6 (Talibov, Mammadov, Badalov)<br>\nBaku State University 1 (Gasimov, Garibzade, Khidirov)<br>\nAzerbaijan State University of Oil and Industry 2 (Musabeyli, Mammadov, Hesenov)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">III DƏRƏCƏLİ DİPLOM<br>\nADA University 2 (Mustafali, Isgandarli, Hasanov)<br>\nBaku Higher Oil School 1 (Huseynli, Bakhshili, Alikhanov)<br>\nADA University 10 (Huseynzade, Farzaliyev, Sadigov)<br>\nBaku Branch of Moscow State University 2 (Plavskiy, Yahyayeva, Perevezenseva)<br>\nADA University 3 (Hasanov, Fahradov, Suleymanov)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">YÜKSƏK NAİLİYYƏT SERTİFİKATI<br>\nBaku State University 5 (Aghabayli, Nabiyev, Gadirli)<br>\nBaku Higher Oil School 2 (Omarov, Rahimli, Karimov)<br>\nQafqaz University 4 (Shikhizade, Jeferov, Alakbarov)<br>\nAzerbaijan State University of Oil and Industry 3 (Alasgarov, Alizada, Hasanov)<br>\nBaku State University 2 (Suleymanov, Azer, Alihaydar)<br>\nNational Aviation Academy 6 (Tagiyev, Mammadov, Orujov)<br>\nBaku State University 3 (Abdullayev, Sofiyev, Shukurzade)<br>\nBaku State University 10 (Ismayilova, Aliyeva, Quliyeva)<br>\nADA University 1 (Ilyasov, Musabayli, Gasimov)</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Müsabiqənin yarımfinal mərhələsi 5-6 dekabr 2015-ci il tarixlərində Gürcüstan Respublikasının Tbilisi şəhərində keçiriləcək.</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Ramin Mahmudzadə<br>\nRegional Director<br>\nACM ICPC NEERC Azərbaycan Subregion</p>\n\n<p style=\"margin: 6px 0px; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">Etibar Seyidzadə<br>\nChief Judje<br>\nACM ICPC NEERC Azərbaycan Subregion</p>\n\n<p style=\"margin: 6px 0px 0px; display: inline; color: rgb(20, 24, 35); font-family: helvetica, arial, sans-serif; font-size: 14px; line-height: 19.32px;\">NAPCAR</p>\n</span>', '2015-10-25 12:43:58', 0, 1, 1),
(12, 'az', 'Studyprog Startap Günlərində 3-cü yerə layıq göruldü', 5, 'studyprog-startap-gunlerinde-3-cu-yere-layiq-goruldu', '<p>Studyprog layihəsi 6-8 noyabrda keçən Startap Günlərində 3-cü yerə layiq görülüb. Sizə <a href=\"http://xeberler.az/new/details/startap-gunleri-2015-in-qalibleri-elan-olundu--13313.htm\">Xəbərlər.az</a> saytından məlumatı çatdırırıq:</p>\n\n\n<p>Günlər çərçivəsində iştirakçılar tərəfindən təqdim edilən 25 &nbsp;ideyanı münsiflər &nbsp;təhlil edib və onlardan &nbsp;6-sı &nbsp;qalib gələrək bu ideya ətrafında komanda formalaşdırmaq və layihə hazırlamaq şansı qazanıb.</p>\n\n<p>Seçilən innovativ biznes ideyaları ətrafında Günlərin iştirakçılarından ibarət olmaqla 4-6 nəfərlik 6 startap komandası formalaşdırılıb.</p>', '<p>Studyprog layihəsi 6-8 noyabrda keçən Startap Günlərində 3-cü yerə layiq görülüb. Sizə <a href=\"http://xeberler.az/new/details/startap-gunleri-2015-in-qalibleri-elan-olundu--13313.htm\">Xəbərlər.az</a> saytından məlumatı çatdırırıq:</p>\n<p>Günlər çərçivəsində iştirakçılar tərəfindən təqdim edilən 25 &nbsp;ideyanı münsiflər &nbsp;təhlil edib və onlardan &nbsp;6-sı &nbsp;qalib gələrək bu ideya ətrafında komanda formalaşdırmaq və layihə hazırlamaq şansı qazanıb. Seçilən innovativ biznes ideyaları ətrafında Günlərin iştirakçılarından ibarət olmaqla 4-6 nəfərlik 6 startap komandası formalaşdırılıb. Seçilmiş komandalara Günlər çərçivəsində beynəlxalq ekspert Justin Crevierin \"Marketing Yourself and your Business \" ( Sizin marketinq və biznesiniz) mövzusunda təlim keçib. Daha sonra Azərbaycan startap sahəsindən yaxından tanıdığımız Orxan Rzayev komandalara “Yeni startapı necə təqdim etməli” mövzusunda təlim keçib. Startap Günləri boyunca komandalar ekspertlərin və mentorların dəstəyi ilə layihələrin ilkin versiyalarının hazırlanması üzərində işləyiblər.</p>\n<p>Startap Günlərinin iştirakçıları eyni zamanda beynəlxalq startap tədbirlərində və beynəlxalq müsabiqələrdə iştirak edən ekspertlərimizlə görüşüblər. Görüş gənc startapçılarla diskussiya şəraitində davam edib. Bu gün isə tədbirin son günü keçirilib və qalib komandalar açıqlanıb. Xeberler.az-ın məlumatına görə, komandalar bu gün səhərdən münsiflər qarşısında layihələrinin ilkin versiyasının-prototiplərinin təqdimatatını ediblər. Hər komandaya çıxış üçün 3 dəqiqə vaxt verilib. Qeyd edək ki, bu mərhələdə 6 komanda–layihə yarışıb:</p>\n<p>Düşünən beyinlər - startapın əsas məqsədi sürücüləri xüsusi proqramlar vasitəsilə avtomobil qəzalarından qorumaqdır. Yaradılan ağıllı qurğular vasitəsilə istifadəçinin təhlükəsizliyi təmin olunur. Çağır Gəlsin - layihə yerli bazar üçün nəzərdə tutulmuş kuryer xidməti göstərən startapdır. Startapın əsas məqsədi müştəriyə ucuz qiymətə xidmət göstərəcək münasib şəxsləri işə cəlb etməkdir. Study Prog - Azərbaycanda olimpiada proqramlaşdırmanın inkişafı üçün yaranıb. Layihə demək olar ki, onlayn təhsil sistemidi, müəllimlər cəlb edildikdən sonra burada vebinar, videomühazirələr və s. yerləşdirmək nəzərdə tutulub. Vahid mütəxəssis bazası- startapın mahiyyəti müxtəlif ixtisaslar üzrə olan mütəxəssisləri bir platformaya toplamaqdır. İşəgötürənlərin işini asanlaşdırmaq üçün nəzərdə tutulub. MusicBeez- bu platforma istifadəçilərə bəyəndikləri musiqini səs çoxluğu ilə seçdikləri müğənnilərdən dinləmək şansı yaradır. Belə ki, istifadəçilər sistemə daxil olur və istədiyi müğənninin başqa müğənniyə aid mahnısını qeyd edir. Daha sonra həmin müğənni səs çoxluğuna görə istəyi dəyərləndirir. Banging Games - Banging tanks müxtəlif yaşlı istifadəçilər üçün nəzərdə tutulmuş oyundur. İstifadəçinin bu oyunu metroda, yolda gedərkən rahatlıqla oynaya bilməsi və asan istifadəsi üçün yaradılıb. Gələcəkdə oyunun dizaynı və funksiyaları daha da təkmilləşdiriləcək.</p>\n<p>Layihələri münsiflər 10 ballıq sistemlə dəyərləndirib. Nəticədə yüksək bal toplayan MusicBeez komandası qalib olub. 2-ci yeri Banging Games, 3-ci yer isə Study Prog layihəsi tutub. Startap Günləri 2015 –in qalib layihələrinə və qalib layihələrin hər bir iştirakçısına ATL Group və Bakcell şirkətlərinin qiymətli hədiyyələri və diplomlar təqdim olunub. Həmçinin tədbirlərin bütün mərhələlərində aktiv iştirak edənlərə \"Startap Azərbaycan \" müsabiqəsinin sertifikatı təqdim edilib.</p>\n<p>Startap Günlərinə Rabitə və Yüksək Texnologiyaları Nazirliyi, İnformasiya Texnologiyalarının İnkişafı Dövlət Fondu, Yüksək Texnologiyalar Parkı, Cybernet, SİNAM, Bakcell şirkətləri və ATL Group şirkəti dəstək verib. Startap Azərbaycan tərəfindən Bakıda Yüksək Texnologiyalar Parkında Startap Günləri keçirilib. Tədbir 3 gün davam edib. Bu günlər ərzində iştirakçılara biznes haqqında təlim keçirilib, startap aləmindən yaxından tanıdığımız məşhur startapçılar onlara biznesin həlli yolları mövzusunda, komanda formalaşdırmaq və ideyanı inkişaf etdirmək haqqında öz fikirlərini bölüşüblər.</p>\n<p>Əli Vəliyev hesab edir ki, Startap Günlərində təcrübəli ekspertlərlə ünsiyyətdə olmaq ona çox şey qazandırıb: “3 gün ərzində keçirilən Günlərdə çoxlu məlumat qazandım. Konfransın birinci günündə ekspertlər arasında müzakirə olunan mövzulardan biri də informatika fənninin tədrisi ilə bağlı yaranan problemlər idi. Mənim layihəm də sırf təhsillə əlaqəli olduğu üçün həvəslə təqdim etdim. Startap günləri maraqlı idi, hesab edirəm ki, uğurlu biznesə doğru addımlamaq istəyən hər bir gəncin yolu startap günlərindən keçməlidir”.</p>\n<p>Səbinə İsayeva Xeberler.az-a bildirir ki, tədbir çərçivəsində iştirakçılar üçün yaradılan imkanlar (dəvət olunmuş təlimçilər, ekspertlər, məşhur startapçılar və s.) yüksək səviyyədə təşkil olunub: “Startap Günləri ərzində çoxlu maraqlı, vacib informasiyalar əldə etdim. Birincisi, biznesi necə yaratmaq olar, onun yollarını öyrəndim. Düşünürəm ki, bu istiqamətdə xarici biznes haqqında məlumatlandırılmaq, ondan bəhrələnmək, uğurlu biznes yaratmağın asan yollarını müzakirə etmək vacib idi. Buna görə də təşkilatçılar tərəfindən dəvət olunan beynəlxalq ekspert Justin Crevierin \"Marketing Yourself and your Business \" ( Sizin marketinq və biznesiniz) mövzusunda keçdiyi təliminə həvəslə qulaq asdım. O cümlədən komandada işləmək, layihəni təqdim etmək, müsahibədə düzgün davranış qaydalarına dair önəmli belə biliklər əldə etdim”.</p>\n<p>Vaqif Kazımov Xeberler.az-a bildirib ki, startap atmosferi ilə tanış olmaq, maraqlı insanlarla ünsiyyət saxlamaq xoş idi. “Startap layihələri haqqında eşitmişdim, amma iştirak etməmişdim. Yaxşı ki gəldim və iştiakçı oldum. Bu 3 gün ərzində startap mühiti ilə tanış olmaq çox maraqlı idi. Burada startapçı üçün layihəni düzgün təqdim etmək, diqqət yetirilməsi vacib olan məqamları bilmək və s. haqqında maraqlı məlumatlar əldə etdim. Hesab edirəm ki, öyrəndiklərimiz gələcək işlərimizdə bizə çox böyük dəstək olacaq”.</p>', '2015-11-08 14:07:39', 0, 1, 1),
(13, 'ru', 'В Азербайджане открылся первый обучающий портал с системой тестирования задач по программированию.', 4, 'в-азербайджане-открылся-первый-обучающий-портал-с-системой-тестирования-задач-по-программированию', '<p>Сегодня открылся первый обучающий портал в&nbsp;Азербайджане, который поможет школьникам и студентам подготавливаться к соревнованиям по программированию.</p>\n', '<p>Сегодня открылся первый обучающий портал в&nbsp;Азербайджане, который поможет школьникам и студентам подготавливаться к соревнованиям по программированию.</p>\n\n\n<p>Тестирующая система на стадии бета-версии уже доступна для проверки задач. Список задач будет пополнен в кратчайшие сроки.</p>\n\n<p>Также отметим, что данный ресурс поддерживает три языка: русский, азербайджанский и английский.</p>\n\n<p>Разработчиками проекта являются студент 4-го курса Бакинского филиала МГУ им. М. В. Ломоносова - Али Велиев и магистрант 1-го курса Бакинского филиала МГУ им. М. В. Ломоносова - Александр Проскуряков. За созданный дизайн и оказанную поддержку благодарим компанию <a href=\"http://bitep.net\">Bitep</a> и интеллектуальный клуб <a href=\"http://qformat.net\">QFormat</a>.Также благодарим студентов Бакинского филиала МГУ им. М. В. Ломоносова Исаеву Сабину и Кязыми Кямрана за перевод интерфейса и статей на английский и азербайджанский языки соответственно.</p>\n\n<p>Обсуждения задач и уроков будут вестись на сайте интеллектуального сообщества <a href=\"http://qformat.net/blog/ocode/\">QFormat</a>.</p>\n\n<p>Желаем всем,&nbsp; кто решил заняться программированием успехов! Мы очень надеемся, что наш проект окажется для Вас полезным.</p>\n\n<p>Помимо этого StudyProg есть в социальных сетях Facebook и ВКонтакте, а также в микроблоге Твиттер.&nbsp;</p>\n', '2013-09-14 06:00:00', 0, 1, 1),
(14, 'ru', 'Сегодня в университете Кавказ состоялся 1/4 финала ACM-ICPC Azerbaijan subregional', 4, 'сегодня-в-университете-кавказ-состоялся-14-финала-acm-icpc-azerbaijan-subregional', '<p>3 ноября 2013 года, в университете Кавказ состоялся четвертьфинал ACM-ICPC IX Azerbaijan Subregional Contest. В контесте приняли участие 45 команд из различных вузов Азербайджана. Официальный результат доступен по <a href=\"http://neerc.ifmo.ru/subregions/standings/azerbaijan-2013.html\">ссылке</a>. Следующий этап пройдёт в городе Тбилиси c 30 ноября по 1 декабря 2013 года.</p>\n', '<p>3 ноября 2013 года, в университете Кавказ состоялся четвертьфинал ACM-ICPC IX Azerbaijan Subregional Contest. В контесте приняли участие 45 команд из различных вузов Азербайджана. Официальный результат доступен по <a href=\"http://neerc.ifmo.ru/subregions/standings/azerbaijan-2013.html\">ссылке</a>. Следующий этап пройдёт в городе Тбилиси c 30 ноября по 1 декабря 2013 года.</p>\n', '2013-11-03 13:39:52', 0, 1, 1),
(15, 'ru', 'В Facebook распространяется новый вирус', 105, 'в-facebook-распространяется-новый-вирус', 'В крупнейшей социальной сети мира начал распространяться новый вирус. Пользователь Facebook видит ссылку на польский сайт, проиллюстрированную фотографией двух людей на капоте автомобиля, передает&nbsp;<a href=\"http://day.az/\" style=\"color: rgb(55, 97, 178); text-decoration: none;\" target=\"_blank\">Day.Az</a>&nbsp;со ссылкой на&nbsp;<a href=\"http://mignews.com/\" style=\"color: rgb(55, 97, 178); text-decoration: none;\" target=\"_blank\">Mignews.com</a>.', 'В крупнейшей социальной сети мира начал распространяться новый вирус. Пользователь Facebook видит ссылку на польский сайт, проиллюстрированную фотографией двух людей на капоте автомобиля, передает&nbsp;<a href=\"http://day.az/\" style=\"color: rgb(55, 97, 178); text-decoration: none;\" target=\"_blank\">Day.Az</a>&nbsp;со ссылкой на&nbsp;<a href=\"http://mignews.com/\" style=\"color: rgb(55, 97, 178); text-decoration: none;\" target=\"_blank\">Mignews.com</a>.\n<p>Заголовок ссылки в переводе с польского означает \"Пойман учитель во время романа со студентом. По делу начато расследование (видео)\". Пользователь, кликнувший на эту надпись, становится жертвой зловреда.&nbsp;</p>\n\n<p>Как отмечают эксперты из \"Лаборатории Касперского, вирус работает следующим образом. У друзей зараженного пользователя Facebook в новостной ленте будет отображаться новость о якобы понравившемся ему сайте. Когда кто-то из друзей кликнет эту новость, у новой жертвы откроется мошенническая страница на польском языке. На этой странице есть скрипт, который без ведома пользователя делает лайк, и вирус распространяется дальше. Одновременно пользователю предлагают просмотреть видео, заплатив с помощью SMS 2,46 злотых.&nbsp;<br />\n<br />\nРанее были зафиксированы аналогичные мошеннические схемы в Рунете.</p>\n', '2013-11-24 07:57:06', 0, 1, 1),
(16, 'ru', 'Google предложил способ перехода с iPhone на Android', 105, 'google-предложил-способ-перехода-с-iphone-на-android', '<p><span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">Председатель совета директоров Google Эрик Шмидт&nbsp;на&nbsp;своей странице в&nbsp;сети Google+&nbsp;предложил перед Рождеством способ перехода на&nbsp;Android-смартфоны для&nbsp;пользователей iPhone, сообщает&nbsp;Digit.ru. </span></p>\n', '<p><span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">Председатель совета директоров Google Эрик Шмидт&nbsp;на&nbsp;своей странице в&nbsp;сети Google+&nbsp;предложил перед Рождеством способ перехода на&nbsp;Android-смартфоны для&nbsp;пользователей iPhone, сообщает&nbsp;Digit.ru. </span></p>\n\n\n<p><span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">В подробном техническом гиде по&nbsp;переходу на&nbsp;операционную систему Android Шмидт описывает способы перенести на&nbsp;новое устройство список контактов, приложения, музыку и&nbsp;фотографии, и&nbsp;одновременно сохранить их в&nbsp;облачном сервисе компании. Также он рекомендует всем пользователям использовать на&nbsp;смартфонах двухфакторную авторизацию и&nbsp;браузер Chrome. По словам Шмидта, многие из&nbsp;его друзей начали использовать вместо iPhone смартфоны на&nbsp;Android, которые обладают высокой производительностью, имеют лучшие экраны и&nbsp;более удобный интерфейс. Он упомянул Nexus 5, Samsung Galaxy S4 и&nbsp;Motorola Droid Ultra как&nbsp;хорошие идеи для&nbsp;рождественских подарков пользователям iPhone. Как сообщал Digit.ru, по&nbsp;данным аналитического агентства Gartner, операционная система Android сейчас занимает первое место в&nbsp;мире по&nbsp;распространенности&nbsp;— ее доля на&nbsp;рынке составляет 81,9%. iOS остается на&nbsp;втором месте, занимая 12,1%. Компания Apple является вторым крупнейшим производителем смартфонов&nbsp;— в&nbsp;третьем квартале этого года, по&nbsp;данным Gartner, она продала более 30 миллионов устройств, что составляет 12,1% рынка. </span></p>\n\n<p><strong><span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">Как Android-смартфоны вытеснили Symbian OS </span></strong></p>\n\n<p><span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">В третьем квартале 2013 года операционная система Android и&nbsp;недорогие смартфоны на&nbsp;ее базе укрепили свои позиции, практически полностью вытеснив операционную систему Symbian компании Nokia. Согласно отчету компании МТС, за&nbsp;год продажи смартфонов, работающих на&nbsp;операционной системе Android, увеличились с&nbsp;64% в&nbsp;третьем квартале 2012 года до&nbsp;75,6% в&nbsp;третьем квартале 2013 года. Рост популярности смартфонов на&nbsp;Android происходит за&nbsp;счет большого количества доступных устройств, которые вызывают интерес у&nbsp;разных целевых аудиторий.</span><br />\n<br />\n<span style=\"background-color:rgb(255, 255, 255); font-family:arial,tahoma; font-size:12px\">Подробности:&nbsp;</span><a href=\"http://www.1news.az/az/economy/tech/20131125125433262.html\" style=\"margin: 0px; padding: 0px; font-family: Arial, Tahoma; color: rgb(0, 0, 0); font-size: 12px; line-height: normal;\">http://www.1news.az/az/economy/tech/20131125125433262.html</a></p>\n', '2013-11-25 11:34:03', 0, 1, 1);
INSERT INTO `articles` (`id`, `language`, `title`, `category`, `slug`, `short`, `content`, `date`, `cover_image`, `author`, `visibility`) VALUES
(17, 'ru', 'Тестирование задач с аналитическим решением.', 4, 'тестирование-задач-с-аналитическим-решением', '<p>Добавлена возможность тестирования задач, имеющих аналитическое решение через более удобный интерфейс.</p>\n\n<p>В настоящее время такими задачами на сайте являются задачи простейшего вариационного исчисления.Решением таких задач являются функции, зависящие от одного вещественного аргумента <b>t</b>. Для того чтобы проверить свое решение введите его в соответствующее поле и нажмите кнопку отправить (все арифметические операции и функции должны быть написаны по правилам языка Си).</p>\n', '<p>Добавлена возможность тестирования задач, имеющих аналитическое решение через более удобный интерфейс.</p>\n\n<p>В настоящее время такими задачами на сайте являются задачи простейшего вариационного исчисления.Решением таких задач являются функции, зависящие от одного вещественного аргумента <b>t</b>. Для того чтобы проверить свое решение введите его в соответствующее поле и нажмите кнопку отправить (все арифметические операции и функции должны быть написаны по правилам языка Си).</p>\n\n\n<p>Для примера рассмотрим задачу <a href=\"http://studyprog.com/problem/show?id=57\">57</a>, ее решением является функция <b>t</b>. Пишем <b>t</b> в соответствующее полеи получаем вердикт <b>Засчитано</b>. Предположим теперь, что мы нашли функцию неправильно, например получили <b>t*t</b>. Пишем ее в указанное поле и получаем вердикт <b>Неверный ответ</b>.</p>\n', '2013-11-25 11:45:34', 0, 1, 1),
(18, 'ru', 'Первая контрольная работа на системе Studyprog', 4, 'первая-контрольная-работа-на-системе-studyprog', '<p>23 декабря 2013 года в Бакинском Филиале МГУ прошло первое тестирование на сервисе StudyProg.</p>\n\n<p>В испытательном соревновании приняло участие 7 человек. Участникам было предложено решить по одной задаче на разные темы по дисциплине \"Оптимизация\". Участники показали положительные результаты, с которыми можно ознакомиться по <a href=\"http://studyprog.com/ru/contest/result/?id=3\">ссылке</a>.</p>\n', '<p>23 декабря 2013 года в Бакинском Филиале МГУ прошло первое тестирование на сервисе StudyProg.</p>\n\n<p>В испытательном соревновании приняло участие 7 человек. Участникам было предложено решить по одной задаче на разные темы по дисциплине \"Оптимизация\". Участники показали положительные результаты, с которыми можно ознакомиться по <a href=\"http://studyprog.com/ru/contest/result/?id=3\">ссылке</a>.</p>\n\n\n<p>Профессор Эльфат Михайлович Галеев и все участники испытания были довольны проведённым мероприятием. Создатели проекта заявили, что будут дальше продолжать улучшать систему, чтобы в будущем на ней можно было бы проводить настоящие зачётные тестирования.</p>\n\n<p>А сейчас ознакомимся с мнением участников испытания и прокоментируем некоторые из них.</p>\n\n<p><strong>Алиева Лейла</strong>: \"Мне понравилось минималистичное оформление сайта. Проверка решенных задач прошла очень быстро, что заметно экономит время. Не понравился долгий процесс регистрации, но, я думаю, это возможно решить\".</p>\n\n<p><strong>Комментарий</strong>: Разумеется можно. В будущем планируется ввести систему Open ID (регистрация через Facebook, Google и т.д.).</p>\n\n<p><strong>Джахангирова Лейла</strong>: \"Система тестирования мне очень понравилась. Быстродействие системы приводит в восторг. Надеюсь в будущем зачёты будут проходить именно таким образом. Я желаю удачи авторам проекта и надеюсь, что в дальнейшем будут предоставлены более обширные возможности системы\".</p>\n\n<p><strong>Исмайлова Лейли</strong>: Хороший сайт, удобный, с хорошим интерфейсом. Особо покопаться не успела, но то, что видела очень даже нормально. Единственно, можно добавить ссылку на помощь на страничку с вводом решения.</p>\n\n<p><strong>Комментарий</strong>: Если есть хоть одно замечание по этому поводу - мы обязаны это исправить.</p>\n', '2013-12-29 04:49:07', 0, 1, 1),
(19, 'ru', 'Поздравления с Днём солидарности всех азербайджанцев и с Новым годом', 4, 'поздравления-с-днём-солидарности-всех-азербайджанцев-и-с-новым-годом', 'Studyprog поздравляет всех с Днём солидарности азербайджанцев всего мира и с Новым годом.<cut></cut> Мы желаем Вам счастья, успехов, побед, а самое главное хотели бы сказать: \"Если у Вас есть какая-то цель, просто не смотря ни на что стремитесь к ней, и удача скорее всего повернётся к Вам лицом\". С НОВЫМ ГОДОМ!!!', 'Studyprog поздравляет всех с Днём солидарности азербайджанцев всего мира и с Новым годом.<cut></cut> Мы желаем Вам счастья, успехов, побед, а самое главное хотели бы сказать: \"Если у Вас есть какая-то цель, просто не смотря ни на что стремитесь к ней, и удача скорее всего повернётся к Вам лицом\". С НОВЫМ ГОДОМ!!!', '2013-12-31 04:45:18', 0, 1, 1),
(20, 'ru', '25 худших паролей в 2013 году', 105, '25-худших-паролей-в-2013-году', '<p>Интернет-ресурс SplashData провел интересное ежегодное исследование и составил рейтинг самых худших паролей 2013 года.</p>\n', '<p>Интернет-ресурс SplashData провел интересное ежегодное исследование и составил рейтинг самых худших паролей 2013 года.</p>\n\n\n<p>Впервые за всю историю подобного мониторинга с лидирующей позиции на второе место ушел пароль \"Password\". В 2013 году самым популярным и в то же время худшим паролем оказалась комбинация \"123456\". Также в рейтинге присутствуют такие пароли, как \"qwerty\", \"iloveyou\", \"1234\" и \"111111\". Рейтинг паролей SplashData основывается на базах данных украденных паролей, которые были найдены в Интернете. Наличие в рейтинге таких паролей, как \"photoshop\" и \"adobe123\" дает понять, что ни в коем случае не нужно генерировать пароль, исходя из названия сайта, который в любой момент может быть взломан. Генеральный директор SplashData заметил интересный факт: повышается популярность простых цифровых паролей. Он находит это странным, ведь большинство сайтов выдвигают очень строгие требования к установке пароля. С рейтингом 25 худших паролей года вы можете ознакомиться ниже.</p>\n<img src=\"http://studyprog.com/images/news/passwordrank.jpg\" />', '2014-01-22 12:59:49', 0, 1, 1),
(21, 'ru', 'Studyprog будет представлен на конференции \"Ломоносов\"', 4, 'studyprog-будет-представлен-на-конференции-ломоносов', '<p>3 марта 2014-го года, в Бакинском филиале МГУ прошёл региональный этап XXI международной конференции студентов, аспирантов и молодых учёных \"Ломоносов\". Доклад \"Расширенная тестирующая система\" был удостоен членами жюри первого места. Конференция пройдёт в Москве, с 7-го по 11-е апреля. Проект будет представлять Проскуряков Александр Игоревич. Желаем удачи!</p>\n', '<p>3 марта 2014-го года, в Бакинском филиале МГУ прошёл региональный этап XXI международной конференции студентов, аспирантов и молодых учёных \"Ломоносов\". Доклад \"Расширенная тестирующая система\" был удостоен членами жюри первого места. Конференция пройдёт в Москве, с 7-го по 11-е апреля. Проект будет представлять Проскуряков Александр Игоревич. Желаем удачи!</p>\n', '2014-03-03 14:05:56', 0, 1, 1),
(22, 'ru', 'В Бакинском филиале МГУ состоялась первая олимпиада на тестирующей системе Studyprog', 4, 'в-бакинском-филиале-мгу-состоялась-первая-олимпиада-на-тестирующей-системе-studyprog', '<p>15 марта 2014-го года в Бакинском филиале МГУ на системе Studyprog прошёл Первый Чемпионат университета. На соревновании участникам было предложено 6 задач на 3 часа. В олимпиаде приняли участие 15 человек. 6 из них были удостоены дипломами 1,2 и 3 степени, а остальные были награждены сертификатами участников. За решённые 4 задачи диплом первой степени получил Плавский Юрий (группа 212), дипломами второй степени были награждены Агаев Газанфар и Исаева Сабина за решённые 3 задачи (группа 211), дипломами 3ей степени за 2 решённые задачи были награждены Кязымов Вагиф, Гейдаров Тимур и Гусейнов Микаил (группа 213). 19 марта прошло награждение победителей.</p>\n', '<p>15 марта 2014-го года в Бакинском филиале МГУ на системе Studyprog прошёл Первый Чемпионат университета. На соревновании участникам было предложено 6 задач на 3 часа. В олимпиаде приняли участие 15 человек. 6 из них были удостоены дипломами 1,2 и 3 степени, а остальные были награждены сертификатами участников. За решённые 4 задачи диплом первой степени получил Плавский Юрий (группа 212), дипломами второй степени были награждены Агаев Газанфар и Исаева Сабина за решённые 3 задачи (группа 211), дипломами 3ей степени за 2 решённые задачи были награждены Кязымов Вагиф, Гейдаров Тимур и Гусейнов Микаил (группа 213). 19 марта прошло награждение победителей.</p>\n\n\n<p>За огранизацию олимпиады хотелось бы сказать \"Спасибо\" доц. Григорьеву Илье Сергеевичу, за оказанную им помощь, поддержу и представленные задачи. Олимпиада прошла на высоком уровне, не было зафиксировано никаких нарушений со стороны участников, никаких спорных вопросов на счёт некорректности условия и тестов к задачам. Система Studyprog полностью оправдала все ожидания разработчиков.</p>\n\n<p>Разработчик проекта Али Велиев заявил: \"Система полностью работоспособна на языках С/С++. В ближайшее время мы внедрим языки Pascal и Java, и с этого момента Studyprog будет полностью готов провести Открытую Республиканскую Олимпиаду не только среди студентов, но и среди всех желающих\".</p>\nВидео с олимпиады:<br />\n<iframe allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"//www.youtube.com/embed/jFewIfv8QUc\" width=\"560\"></iframe><br />\nВидео с награждения:<br />\n<iframe allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"//www.youtube.com/embed/kMq8FbURT7I\" width=\"560\"></iframe>', '2014-03-20 09:48:50', 0, 1, 1),
(23, 'ru', 'Studyprog покорил \"Ломоносов 2014\"', 4, 'studyprog-покорил-ломоносов-2014', '<p>C 7 по 11 апреля в МГУ проходил Международный молодежный научный форум «Ломоносов». Форум включал в себя одноименную конференцию, всероссийский конкурс студенческих бизнес-идей «Потенциал будущего», выставку образовательных программ МГУ, форум «Новое Поколение-2014» и другие мероприятия.</p>\n', '<p>C 7 по 11 апреля в МГУ проходил Международный молодежный научный форум «Ломоносов». Форум включал в себя одноименную конференцию, всероссийский конкурс студенческих бизнес-идей «Потенциал будущего», выставку образовательных программ МГУ, форум «Новое Поколение-2014» и другие мероприятия.</p>\n\n\n<p>Доклад «Расширенная тестирующая система» магистранта 1 года обучения и студента 4 курса факультета прикладной математики Проскурякова Александра и Велиева Али были признаны лучшим докладом секции. (<a href=\"http://msu.az/ru/news-view/123-%D0%98%D1%82%D0%BE%D0%B3%D0%B8%20%D0%9C%D0%B5%D0%B6%D0%B4%D1%83%D0%BD%D0%B0%D1%80%D0%BE%D0%B4%D0%BD%D0%BE%D0%B9%20%D0%BD%D0%B0%D1%83%D1%87%D0%BD%D0%BE%D0%B9%20%D0%BA%D0%BE%D0%BD%D1%84%D0%B5%D1%80%D0%B5%D0%BD%D1%86%D0%B8%D0%B8%20%D1%81%D1%82%D1%83%D0%B4%D0%B5%D0%BD%D1%82%D0%BE%D0%B2,%20%D0%B0%D1%81%D0%BF%D0%B8%D1%80%D0%B0%D0%BD%D1%82%D0%BE%D0%B2%20%D0%B8%20%D0%BC%D0%BE%D0%BB%D0%BE%D0%B4%D1%8B%D1%85%20%D1%83%D1%87%D0%B5%D0%BD%D1%8B%D1%85%20%C2%AB%D0%9B%D0%BE%D0%BC%D0%BE%D0%BD%D0%BE%D1%81%D0%BE%D0%B2-2014%C2%BB\">источник</a>)</p>\n\n<p>Отметим, что несмотря на столь короткий срок существования Studyprog, он уже успел зарекомендовать себя как надёжная тестирующая система, помощник по решению задач и по подготовке к разного рода мероприятиям по проверке знаний. Также Studyprog является участником проекта <a href=\"http://www.netty.az/cgi-bin/onelike.cgi?id=49\">NETTY</a></p>\n', '2014-04-19 14:25:02', 0, 1, 1),
(24, 'ru', 'Стали известны результаты Республиканской олимпиады по программированию среди студентов ВУЗов', 4, 'стали-известны-результаты-республиканской-олимпиады-по-программированию-среди-студентов-вузов', 'Организованный Министерством Связи и Высоких Технологий, Фондом Гейдара Алиева и Институтом Информационных Технологий НАНА финал <a href=\"http://olimpiada.az\">Чемпионата Азербайджана по программированию среди студентов</a> прошёл 26-го апреля 2014 года в ИИТ НАНА.', 'Организованный Министерством Связи и Высоких Технологий, Фондом Гейдара Алиева и Институтом Информационных Технологий НАНА финал <a href=\"http://olimpiada.az\">Чемпионата Азербайджана по программированию среди студентов</a> прошёл 26-го апреля 2014 года в ИИТ НАНА. В финале приняло участие 28 команд (10 из университета \"Кавказ\", 3 из Бакинского филиала МГУ, 7 из БГУ, 1 из АТУ, 2 из АГНА, 3 из БВНШ, 1 из Нахчиванского и 1 из Гянджинского университета). Участникам было предложено решить 10 задач за 5 часов.\n<p>В результате были выявлены 3 победителя:</p>\n\n<p><b>I МЕСТО</b></p>\n\n<p>Qafqaz Programmers - университет \"Кавказ\".</p>\n\n<p><b>II МЕСТО</b></p>\n\n<p>MSU Programmers - Бакинский филиал МГУ</p>\n\n<p><b>III МЕСТО</b></p>\n\n<p>Qafqaz U4 -&nbsp;университет \"Кавказ\".</p>\n\n<p>Победители будут награждены ценными призами от компании HP. Поздравляем!</p>\n&nbsp;', '2014-04-28 12:53:42', 0, 1, 1),
(25, 'ru', 'Studyprog обновился до версии 2.0', 4, 'studyprog-обновился-до-версии-20', '14 сентября 2013-го года был запущен проект Studyprog. Главной целью этого проекта была проверка олимпиадных задач и проведение соревнований на сайте. Но позже на сайте впервые в мире появилась возможность тестировать задачи высшей математики. В класс таких задач входили задачи вычисления квадратурных формул, задачи оптимизации и выпуклого анализа, а также задачи вычислительной математики.', '14 сентября 2013-го года был запущен проект Studyprog. Главной целью этого проекта была проверка олимпиадных задач и проведение соревнований на сайте. Но позже на сайте впервые в мире появилась возможность тестировать задачи высшей математики. В класс таких задач входили задачи вычисления квадратурных формул, задачи оптимизации и выпуклого анализа, а также задачи вычислительной математики.<br />\nСегодня же мы выпускаем новую версию проекта:<br />\n1. Новый дизайн. Каркас сайта написан на разметке Bootstrap. Это позволяет адекватно отображать его на смартфонах и планшетах. Сайт посажен на MVC framework Qbit 3. Использованные языки: HTML5, CSS3, Javascript, PHP, MySql, Shell. Также внедрено большое количество jQuery плагинов.<br />\n2. Теперь для компиляции задач доступны 4 компилятора: С (gcc), С++ (g++), Java (jdk) и Pascal (fpc). Это выводит Studyprog на уровень проведения соревнований, скажем среди школьников.<br />\n3. На сайте любой пользователь, имеющий определённые права может вести собственный блог. Как пример, этим могут заниматься преподаватели информатики.<br />\n4. Исправлены системные баги.<br />\n5. Сайт оснащён ректорами LaTeX и MathML.<br />\n6. Дружелюбный интерфейс для пользователей и больше полезной литературы по всем направлениям математики.<br />\nТакже подписывайтесь на нас в соц. сетях:<br />\nFacebook: <a href=\"https://www.facebook.com/studyprog\">https://www.facebook.com/studyprog</a><br />\nTwitter: <a href=\"https://twitter.com/StudyProg\">https://twitter.com/StudyProg</a><br />\nВКонтакте: <a href=\"http://vk.com/studyprog\">http://vk.com/studyprog</a><br />\nGoogle+: <a href=\"https://plus.google.com/+Studyprog\">https://plus.google.com/+Studyprog</a><br />\nYoutube: <a href=\"https://www.youtube.com/user/studyprog\">https://www.youtube.com/user/studyprog</a><br />\nInstagram: <a href=\"http://instagram.com/studyprog\">http://instagram.com/studyprog</a><br />\n<br />\nЕсли Вы являетесь преподавателем, то Вы сможете стать администратором проекта написав письмо по адресу: <a href=\"mailto:admin@studyprog.com\">admin@studyprog.com</a><br />\nЕсли Вы хотите добавить задачу, Вы можете отправить письмо адресу <a href=\"mailto:problems@studyprog.com\">problems@studyprog.com</a>.<br />\nДля публикации статьи обращайтесь по адресу <a href=\"mailto:article@studyprog.com\">article@studyprog.com</a><br />\nВаши предложения по улучшению проекта мы рады видеть на <a href=\"mailto:partners@studyprog.com\">partners@studyprog.com</a><br />\n<br />\nТакже хотим поблагодарить наших партнёров: <a href=\"http://bitep.net\">компанию BITEP</a> и <a href=\"http://qformat.net\">интеллектуальный клуб QFormat</a>.<br />\n<br />\nБолее детальную информацию о проекте можно получить в разделах <a href=\"http://studyprog.com/about/\">\"О проекте\"</a> и <a href=\"http://studyprog.com/help/\">\"Помощь\"</a>', '2014-09-01 06:00:00', 0, 1, 1),
(26, 'ru', 'Результаты Открытого Кубка им. Лотфи-Заде 2014', 4, 'результаты-открытого-кубка-им-лотфи-заде-2014', '<p>\n  21 сентября 2014-го года в университете Кавказ состоялся первый Открытый Кубок им. Лотфи-Заде по программированию. Ведущим мероприятия был старший преподаватель университета \"Кавказ\" Этибар Сеидзаде. В начале мероприятия выступили организаторы и члены жюри (в составе с доц. Рамином Махмудзаде, доц. Абзеддином Адамовым, Али Гасановым, Тофигом Гасановым, Бахрузом Гарамамедовым, Адылем Алиевым и Назимом Сулейманлы) и пожелали участникам удачи, а также рассказали идею создания данного соревнования.</p>', '<p>\n  21 сентября 2014-го года в университете Кавказ состоялся первый Открытый Кубок им. Лотфи-Заде по программированию. Ведущим мероприятия был старший преподаватель университета \"Кавказ\" Этибар Сеидзаде. В начале мероприятия выступили организаторы и члены жюри (в составе с доц. Рамином Махмудзаде, доц. Абзеддином Адамовым, Али Гасановым, Тофигом Гасановым, Бахрузом Гарамамедовым, Адылем Алиевым и Назимом Сулейманлы) и пожелали участникам удачи, а также рассказали идею создания данного соревнования.</p><p>Кубок Лотфи-Заде является аналогом Кубка Векуа, который на международном масштабе проводится каждый год в Грузии. Организаторы выразили своё мнение относительно нынешнего мероприятия и заявили, что массовое участие в данном мероприятии также выведет его на международный уровень и ещё раз прославит имя великого азербайджанского учёного. Также было кратко рассказано про биографию Лотфи-Заде. За создание задач выпускникам университета \"Кавказ\" была выражена благодарность.\n</p>\n<p>\n  После открытия Кубка участники приступили к решению 9-ти задач в течении 5-ти часов на системе <a href=\"http://e-olimp.com.ua\">e-olimp</a>. В мероприятии приняли участие 49 участников из разных ВУЗ-ов Азербайджана, в том числе и вне конкурса из стран Европы участвовали бывшие выпускники азербайджанских ВУЗов. В результате всем участникам были розданы майки с логотипом мероприятия, а также сертификаты за участие. Участники решившие 3-4 задачи были награждены дипломами третьей степени, 5 задач - второй степени, 6-7 задач - первой степени.\n</p>\n<p>\n  Первое место, Кубок и золотую медаль получил студент университета \"Кавказ\" Рашид Мамедов за 7 решёных задач.\n</p>\n<p>\n  Второе место и серебряные медали получили магистрант Бакинского филиала МГУ им. М. В. Ломоносова Велиев Али и студент университета \"Кавказ\" Махмуд Аллахвердиев.\n</p>\n<p>\n  Третье место и бронзовые медали достались студентам университета \"Кавказ\" Тебриз Гаджиев, Эльми Ахмедов и магистранту Азербайджанской Государственной Академии Мусагилю Мусабейли.\n</p>\n<p>\n  Победителям также были вручены ценные призы.\n</p>\n<p>\n  Также символические призы были вручены организаторам и членам жюри данного мероприятия.\n</p>\n<p>\n  Предлагаем вниманию читателей видео с награждения участников из Бакинского филиала МГУ.\n</p>\n<iframe allowfullscreen=\"\" frameborder=\"0\" height=\"315\" src=\"//www.youtube.com/embed/t47m2WlOeU0\" width=\"560\"></iframe>', '2014-09-21 13:24:36', 0, 1, 1),
(27, 'ru', 'Результаты \"ACM ICPC X Azerbaijan Subregional Championship\"', 4, 'результаты-acm-icpc-x-azerbaijan-subregional-championship', 'В университете Кавказ прошёл четвертьфинал “39-го Чемпионата Мира по программированию среди студентов ACM ICPC” (X Чемпионат Азербайджана).', 'В университете Кавказ прошёл четвертьфинал “39-го Чемпионата Мира по программированию среди студентов ACM ICPC” (X Чемпионат Азербайджана).<br />\nПри поддержке университета \"Кавказ\", Бакинского Государственного Университета, NAPCAR, IEEE Computer Society Azərbaycan bölməsi, IEEE Telecommunication Society Azərbaycan bölməsi, ACM Azərbaycan bölməsinin təşkilatı 9 ноября 2014-го года в университете \"Кавказ\" прошёл четвертьфинал “39-го Чемпионата Мира по программированию среди студентов ACM ICPC” (X Чемпионат Азербайджана).<br />\nВ соревновании приняло участие 58 команд из 14 университетов и 3 школьные команды (вне конкурса)<br />\nУниверситет \"Кавказ\" – 10<br />\nБакинский филиал МГУ – 8<br />\nБакинский Государственный Университет – 8<br />\nАзербайджанская Государственная Нефтяная Академия – 6<br />\nАзербайджанская Национальная Академия Авиации – 6<br />\nУниверситет \"АДА\" – 5<br />\nВысшая Нефтяная школа Баку - 3<br />\nАзербайджанский Технический Университет – 3<br />\nУниверситет \"Хазар\" – 3<br />\nУниверситет \"Азербайджан\" – 3<br />\nАзербайджанский Архитектурно-строительный Университет – 1<br />\nАзербайджанский Государственный Педагогический Университет – 1<br />\nНахичеванский Государственный Университет – 1<br />\nУниверситет \"Одлар Юрду\" - 1<br />\nШкольники – 3 (вне конкурса)<br />\nпредставляли свои университеты в командном виде (в каждой команде по 3 человека).<br />\nКомандам было дано решить 12 алгоритмических задач за 5 часов. Оценивание проводилось с помощью автоматической тестирующей системы e-olimp.com.ua/az<br />\nКоманда Qafqaz U 1 университета \"Кавказ\" удостоилась I места; Qafqaz U 2 II места; Qafqaz U 3 и Qafqaz U 5 III и команды Бакинского филиала МГУ BakuMSU1 и BakuMSU8 III места.<br />\nКоманды Университета \"Кавказ\" Qafqaz U 6, Qafqaz U 4, команда Азербайджанской Государственной Нефтяной Академии Az SOA 5, Бакинского Государственного Университета Baku SU1, BakuSU 3, Baku SU 2, Бакинского филиала МГУ BakuMSU2, школьников SHOOL1 и SHOOL2 удостоились диплома III степени.<br />\nПобедители конкурса получают право участвовать в полуфинале “39-го Чемпионата Мира по программированию среди студентов ACM ICPC” и Открытого Чемпионата Южного Кавказа который пройдёт 6-7 декабря 2014-го года в городе Тбилиси.<br />\n<br />\n<a href=\"[[constant name=portal_url]]pages/getPage?p=acm_azerbaijan2014\">Результаты</a><br />\n<br />\nI МЕСТО<br />\nКоманда Qafqaz U 1<br />\nMəhəmməd Vəliyev, Elmi Əhmədov, Təbriz Hacıyev<br />\n<br />\nII МЕСТО<br />\nКоманда Qafqaz U 2<br />\nRəşad Məmmədov, Qalib Sarayev, Eldar Həsənov<br />\n<br />\nIII МЕСТО<br />\nКоманда Qafqaz U 3<br />\nNurlan Əliyev, Rövşən Hüseynov, Mahmud Allahverdiyev<br />\n<br />\nIII МЕСТО<br />\nКоманда BakuMSU1<br />\nAleksandr Proskuryakov, Əli Vəliyev, Səbuhi Əzimzadə<br />\n<br />\nIII МЕСТО<br />\nКоманда Qafqaz U 5<br />\nƏləkbər Vəlizadə, Hidayət Soltanzadə, Orxan İsmayilov<br />\n<br />\nIII МЕСТО<br />\nКоманда BakuMSU8<br />\nQəzənfər Ağayev, Şahin Kazımov, Bahri Abdullaxan<br />\n<br />\nИсточник: Этибар Сеидзаде, группа National Association of Programming Contestants of Azerbaijan Republic в Facebook.', '2014-11-11 15:09:05', 0, 1, 1),
(28, 'ru', 'Проект Studyprog магистрантов Бакинского филиала МГУ вошел в тройку лучших премии Milli Net 2014', 4, 'проект-studyprog-магистрантов-бакинского-филиала-мгу-вошел-в-тройку-лучших-премии-milli-net-2014', '19 декабря в Баку Бизнес Центре состоялась церемония награждения победителей премии Milli Net 2014 – Национальный Интернет 2014.<span style=\"line-height: 20.7999992370605px;\">', '19 декабря в Баку Бизнес Центре состоялась церемония награждения победителей премии Milli Net 2014 – Национальный Интернет 2014.<span style=\"line-height: 20.7999992370605px;\"></span> На 6-ой церемонии вручения премии Milli Net 2014 от имени организационного комитета выступил президент Интернет-форума Азербайджана Осман Гюндуз, который рассказал о Milli Net 2014 и о работах, проделанных в рамках конкурса.<br />\nБыло отмечено, что в 14 номинациях были представлены 322 сайта, из которых 272 допущены к конкурсу. Сайт www.studyprog.com, созданный магистрантами Филиала МГУ имени М.В.Ломоносова в г. Баку Проскуряковым Александром и Велиевым Али занял почетное третье место в конкурсе Milli Net 2014.<br />\nОтметим, что Studyprog – первая в Азербайджане система автоматического тестирования задач по олимпиадному программированию, численным методам и другим различным разделам математики. Целью создания данного проекта является помощь в обучении программированию школьникам и студентам. Проект пополняется базой учебных материалов и задач, которые помогут всем желающим освоить любой материал в данной области науки.<br />\nСайт функционирует на трех языках – азербайджанском, русском и английском. Посредством данной тестирующей системы были проведены контрольные по предмету методы оптимизации и чемпионат по программированию среди студентов Бакинского Филиала МГУ. В настоящее время в системе имеется возможность для проведения олимпиад по программированию среди школьников и студентов Азербайджана.', '2014-12-19 17:31:08', 0, 1, 1),
(29, 'ru', 'UX Azerbaijan', 106, 'ux-azerbaijan', '9-го февраля 2015-го года в офисе инновационного центра компании Azercell - \"Барама\", состоялось мероприятие, посвящнное понятию пользовательского опыта и удобства пользователей при использовании IT продуктов.', '9-го февраля 2015-го года в офисе инновационного центра компании Azercell - \"Барама\", состоялось мероприятие, посвящнное понятию пользовательского опыта и удобства пользователей при использовании IT продуктов. Мероприятие состояло из двух частей. В первой части мероприятия выступил представитель компании Keytorc Барыш Сарыалиоглу. В своей презентации он рассказал о различиях понятий UX (user experience) и UI (user interface), о поведении недовольных пользователей, критерий удобств и их аспектов и частых ошибках разработчиков продуктов.<br />\nВторую часть мероприятия провёл представитель компании Azercell Эмиль Исмаилханов, который рассказал о вредрении понятий UX в продукты компании Azercell.<br />\nВ конце мероприятия среди зрителей были розыграны призы - книги и билет на участие в конференции по UX в Стамбуле.', '2015-02-09 14:06:41', 0, 1, 1),
(30, 'ru', 'Азербайджан и Сингапур выбраны для проведения IOI в 2019 и 2020 годах', 106, 'азербайджан-и-сингапур-выбраны-для-проведения-ioi-в-2019-и-2020-годах', '<p>В 2019 и в 2020 годах Международная олимпиада по информатике (IOI) пройдет в Азербайджане и Сингапуре. Об этом корреспонденту МИА «Казинформ» сообщил президент IOI, профессор департамента информатики Нового Болгарского университета Крассимир Манев.</p>\n', '<p>В 2019 и в 2020 годах Международная олимпиада по информатике (IOI) пройдет в Азербайджане и Сингапуре. Об этом корреспонденту МИА «Казинформ» сообщил президент IOI, профессор департамента информатики Нового Болгарского университета Крассимир Манев.</p>\n\n\n<p>«Сегодня на совете руководителей были объявлены страны, принимающие у себя Международную олимпиаду по информатике. В 2019 хозяином соревнований станет Азербайджан. Но так как в этот раз было сильное желание Сингапура принимать у себя олимпиаду, то мы решили в этом году выбрать два государства. Таким образом, в 2020 году олимпиада будет проходить в Сингапуре», - сказал К.Манев.</p>\n\n<p>Напомним, что в этом году Казахстан впервые принимал у себя Международную олимпиаду по информатике, на которую приехали свыше 630 делегатов из 83 стран мира. По итогам двух дней соревнований лучшим стал школьник из Южной Кореи Джи Хак Юн, который набрал 600 баллов из 600 возможных. Казахстанская сборная завоевала три «серебра» и одну «бронзу».</p>\n\n<p>В 2016 году олимпиада впервые пройдет в столице Татарстана Казани на базе Казанского федерального университета. В 2017-ом олимпиаду примет у себя Иран, в 2018 - Япония.</p>\n', '2015-08-08 08:01:46', 0, 1, 1),
(31, 'en', 'It was opened the first training portal in Azerbaijan with the online programming problems judging system.', 6, 'it-was-opened-the-first-training-portal-in-azerbaijan-with-the-online-programming-problems-judging-system', '<p>Today it has been opened the first training portal in Azerbaijan which would help schoolboys and students to get prepared to programming contests.&nbsp;</p>\n', '<p>Today it has been opened the first training portal in Azerbaijan which would help schoolboys and students to get prepared to programming contests.&nbsp;</p>\n\n\n<p>Testing system is in the beta-version release and is already available for checking your solutions. Task list will be topped up as soon as possible.</p>\n\n<p>We also want to add that this resource has three language packs: Russian, Azeri and English.&nbsp;</p>\n\n<p>This project was created by Ali Veliyev (4<sup>th</sup> year student in Baku branch of MSU named after M.V. Lomonosov) and Alexander Proskuryakov (1<sup>st</sup> year master in Baku branch of MSU named after M.V. Lomonosov). We are grateful to company \"<a href=\"http://bitep.net\">Bitep</a>\"&nbsp;and intellectual club “<a href=\"http://qfotmat.net\">QFormat</a>” for support. We are also grateful to students of Baku branch of MSU named after M.V. Lomonosov,&nbsp; Isayeva Sabina and Kamran Kazimi for interface translation into English and Azeri.</p>\n\n<p>The problems and lessons will be discussed on website of intellectual club of “<a href=\"http://qformat.net/blog/ocode/\">QFormat</a>” community.</p>\n\n<p>We want to wish good luck to everyone who decided to start programming. We hope that our project will be very useful for you.</p>\n\n<p>You can follow StudyProg &nbsp;in FB , VK, Twitter.&nbsp;</p>\n', '2013-09-14 06:00:00', 0, 1, 1),
(32, 'az', 'Alqoritmlərin quruluşu bairədə və məsələlərin həlli üçün nə bilmək lazımdır?', 108, 'alqoritmlerin-qurulushu-bairede-ve-meselelerin-helli-uchun-ne-bilmek-lazimdir', '<p>Bu gün dünyada proqramlaşdırma peşəsi ən gərəklilərindəndir.</p>\n\n<p>Bəs \"proqramçı\" deyəndə kim nəzərdə tutulur? Bütün gün mənasiz kod yazan adam? Və niyə mənasız? Bəlkə bir mənası var?</p>', '<p>Bu gün dünyada proqramlaşdırma peşəsi ən gərəklilərindəndir.</p>\n\n<p>Bəs \"proqramçı\" deyəndə kim nəzərdə tutulur? Bütün gün mənasiz kod yazan adam? Və niyə mənasız? Bəlkə bir mənası var?</p>\n\n<p>Əlbəttə, bu peşəyə ümumi tələb ilə yanaşı, bu həmdə alqoritmik zəka tələb edir.</p>\n\n<p>Bəs \"alqoritm\" nədir?</p>\n\n<p>Bu sualın cavabını, məsələn, Vikipediyada, tapa bilərsiniz.</p>\n<cut> <i>Bilmək lazımdır ki, proqramçı ilk növbədə alqoritmlər ilə işləyir. Bizim saytda \"Kodlaşdırma\" bölməsi var. Çox güman ki, saytımızın bu hissi \"koder\"lərə yardımcı olacaq. Adətən hazır alqoritmlərlə işləyənə \"koder\" deyirlər. Bizim resurs həm alqoritm hazırlayanlar, həm də \"koder\"lər üçündür.</i>\n\n<p>İndi alqoritmin hazırlanma prosesinə nəzər salaq.</p>\n\n<ul>\n	<li>Əvvəlcə qarşımıza qoyulan məqsədi diqqətlə incələmək lazımdır. Proqramın girişini və çıxışını bəlirləmək lazımdır.</li>\n	<li>Məsələnin həlli üçün alqoritmi birbaşa hazırlamaq lazımdır.</li>\n	<li>Həlli elə maksimal dərəcədə optimallaşdırmaq lazımdır ki, mümkün qədər az misal həll etsin. Sturtur məlumatlarının istifadə etdiyi yaddaşın həcmini minimallaşdırmaq lazımdır.</li>\n	<li>Bizə lazım olan alqoritmi əldə etdikdə, onu reallaşdırmaq lazımdır. Alqoritmi funksiyalar və prosedurların reallaşdırdıqı hissələrə maksimal dərəcədə çox hissələrə, bölünməmək dərəcəsinə çatana qədər, bölmək lazımdır. Bundan sonra əsas funksiyadan bu funksiyaların superpozisiyalarını yaratmaq lazımdır.</li>\n	<li>Hər funksiyanın öz alqoritmini yerinə yetirməsini diqqətlə yoxlayın.</li>\n</ul>\n\n<p>Bu qaydalardan istifadə etməklə istədiyiniz alqoritmin doğru reallaşdırılmasına vasitə olacaq. Amma əgər sizdə alınmasa, hara müraciət etmək lazımdır, bilirsiniz.</p>\n\n<p>Suallarınızı <a href=\"qformat.net\">QFormat</a> intellektual qrupunda və ya bizim <a href=\"http://www.facebook.com/groups/studyprog/\">facebook qrupumuzda</a> verə bilərsiniz. Gələn görüşlərə qədər.</p>\n\n<p>Tərcüməyə görə Səmədov Bəhruza təşəkkür bildiririk.</p>', '2014-07-04 03:28:43', 0, 1, 1),
(33, 'az', 'Alqoritmlərin mürəkkəbliyi', 108, 'alqoritmlerin-murekkebliyi', '<p>Məsələnin şərtini garşımıza goyandan sonra bizim əsas məqsədımız bütün testlərə düzgün cavab verən, tələb olunan vaxt və yaddaş limitinə uyğun olan algoritmı tərtib etməkdir.</p>', '<p>Məsələnin şərtini garşımıza goyandan sonra bizim əsas məqsədımız bütün testlərə düzgün cavab verən, tələb olunan vaxt və yaddaş limitinə uyğun olan algoritmı tərtib etməkdir.</p>\n\n<p><strong><em>Tərif 1.</em></strong> Əgər əməliyyatı algoritmdə vahid addım kimi təsfir etmək olarsa onu elementar adlandırırlar. Məsələn: şərtin yoxlanması, məlumatın oxunması və s. elementar əməliyyatlardılar.</p>\n\n<p>Tutaq ki, <em><strong>f </strong></em>və <em><strong>g</strong></em> iki  (həqiqi ədədləri həqiqi ədədlərə əks etdirən) funksiyadır. Əgər <em><strong>f</strong></em> funksiyası <strong><em>g</em></strong> funksiyasından tez artmır, onda deyilir ki, <em><strong>f</strong></em> bərabərdir O(<em><strong>g</strong></em>).</p>\n\n<p>Tutaq ki, <em><strong>f </strong></em>və <em><strong>g</strong></em> iki  (həqiqi ədədləri həqiqi ədədlərə əks etdirən) funksiyadır. Əgər <em><strong>f</strong></em> funksiyası O(<strong><em>g</em></strong>) bərabərdir sə, onda deyilir ki, <em><strong>g</strong></em> bərabərdir &Omega;(<strong><em>f</em></strong>).</p>\n\n<p>Algoritmin müəyyən verilənlərı daxil etdikdən sonrakı işini eksperiment adlandırırıq. Eksperimentlərin sayı verilənərin sayənı artirdiqca sonsuzluğa yaxınlaşır.&nbsp;</p>\n\n<p>Tutaq ki, işləmə vaxtının ardıcıllığı həqiqi oxda olan <em><strong>f</strong></em> funksiyasını təyin edir. Deyilir li, algoritm O(<em><strong>g</strong></em>), zamanında işləyir, əgər elə <em><strong>g</strong></em> funksiyası mövcuddur ki, <em><strong>f</strong></em>  O(<em><strong>g</strong></em>)-di və istənilən digər <em><strong>h</strong></em> O(<strong><em>g</em></strong>) olaraq &Omega;(<em><strong>f</strong></em>)-ə bərabər deyil.&nbsp;</p>\n\n<p><strong><em>Tərif 2.</em></strong> Əgər algoritm verilənlərin sayı sonsuzluğa yaxınlaşdiqca O(<strong><em>f</em></strong>) elementar əməliyyat yerinə yetirir, onda <strong><em>f</em></strong> funksiyası algoritmin mürəkkəbliyi adlanır.</p>\n\n<p>Mühazirəni hazırladı: <a href=\"http://studyprog.com/ru/profile/show/?username=admin\">Əli Vəliyev</a>.</p>\n\n<p>Mənbələr: <a href=\"http://www.wikipedia.org/\">Vikipediya</a>, <a href=\"http://www.intuit.ru/\">İnternet-Universitet &quot;İntuit&quot;</a>,&nbsp;Makkonel C. - Algoritm əsasları.</p>\n<p>Tərcümə - <a href=\"http://studyprog.com/ru/profile/show/?id=3\">İsayeva Səbinə</a></p>', '2014-08-16 13:50:44', 0, 1, 1),
(34, 'az', 'Ardıcıl axtarış', 109, 'ardicil-axtarish', '<p>Bütün sonrakı alqoritmlər növlərə ayırmaları üçün bir vəzifənin həllinə xidmət edir: Həmin növlərə ayırmaq massivi. Təlimlərdə \"bu\" mənada biz tam ədədlər dərk edəcəyik. Lakin gerçəkləşdirilməsi əlavə <b>int compare()</b> funksiyaları istifadə etməklə ümumi halda gedəcək.', '<p>Bütün sonrakı alqoritmlər növlərə ayırmaları üçün bir vəzifənin həllinə xidmət edir: Həmin növlərə ayırmaq massivi. Təlimlərdə \"bu\" mənada biz tam ədədlər dərk edəcəyik. Lakin gerçəkləşdirilməsi əlavə <b>int compare()</b> funksiyaları istifadə etməklə ümumi halda gedəcək. Belə olan halda biz nəinki artması qaydada, həm də убавания qaydada, habelə xüsusi meyara (məsələn müəyyən verib ki, sayı az olsa onun vahidlərinin sayı azdır, sayından asılı olmayaraq onlarla və digər kateqoriyaları) görə çeşidləmək bilərik. Ayrıca funksiyası da istifadə olunacaq - b-void swap () - / b- ilə paralel bir massivinin çeşidlənməsi, növlərə ayırmaq ikinci (məsələn, x координате üzrə nöqtələrinin koordinatlarının çeşidlənməsi) imkan verəcək. Halbuki bu, işin (əlavə funksiyaların dəfələrlə çağırış) sürəti azaldır, amma asan yadda alqoritm kömək edir və əgər lazımdırsa və kodu.</p>\n\n<p>Hər hansı verilmiş elementi tapmaq lüzumu ildə verilmiş siyahıda tez-tez yaranır. Bu заданый element məqsədli adlanır. Siyahı üzrə elementlərin gizlətməyə неотсортированным sayılır. Biz də bu növlərə ayırılmış siyahıda ardıcıl axtarışlar alqoritmdə barədə danışaq.</p>\n\n<p>Qoy bizim ardıcıllığı N elementləri də var. Alqoritm ideyası məqsədli ilə müqayisədə ardıcıl şəkildə yoxlamada elementlərinin və onların ibarətdir. Aydındır ki, N maksimum sayı müqayisə oluna bilər, çünki düz N müqayisə ən pis halda iki alqoritm (o ardıcıllıqla məqsədli element və ya məqsədli element son siyahıda yoxdur) tələb edir. Əgər müqayisə N daha çox olardı ki, bu bir elementdir, iştirak edən bir dəfədən artıq müqayisədə var idi. O fikirlərdə minimallığı əməliyyatlarının ən pis hal üçün ziddiyyət yaranır. İş vaxtı ardıcıl axtarış O (N), həm də müqayisəsi zamanı nəzərə alınır ki, hər tip məlumatların müqayisə üçün deyil bir əməliyyat (məsələn ayın 64#битные üçün maşına 32#битной) tələb edir.</p>\n\n<p>Следующие реализации обходят массив целых чисел, сравнивают каждый элемент с целевым элементов <b>target</b> и возвращают индекс элемента. Если целевой элемент не найден, то возвращается несуществующее значение индекса.</p>\n\n<p>Реализация последовательного поиска на Pascal:</p>\n\n<pre class=\"brush: pascal;\">\nProgram Sequental_Search;\ntype intarray = array[1..100] of integer;\nvar \n    mas : intarray;\n    n, i, target : integer;\n\nfunction SequentalSearch(mas : intarray; n, target : integer ) : integer;\nvar\n    i : integer;\nbegin\n    SequentalSearch := 0;\n    for i := 1 to n do\n    if ( mas[i] = target ) then SequentalSearch := i;\nend;\n\nbegin\n    readln(n);\n    for i:=1 to n do\n    read(mas[i]);\n    read(target);\n    writeln(SequentalSearch(mas,n,target));\nend.\n</pre>\n\n<p>Реализация последовательного поиска на C:</p>\n\n<pre class=\"brush: c;\">\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n\nint SequentalSearch( int*, int, int );\nint main(void) {\n    int *mas, n, i, target;\n    scanf( \"%d\", &amp;n );\n    mas = ( int* ) malloc(n * sizeof(int));\n    for ( i = 0; i &lt; n; i++ ) scanf( \"%d\", &amp;mas[i] );\n    scanf( \"%d\", &amp;target );\n    printf(\"%d\n\", SequentalSearch(mas,n,target ) );\n    return 0;\n}\n\nint SequentalSearch( int *mas, int n, int target) {\n    int i;\n    for ( i = 0; i &lt; n; i++ ) {\n        if ( mas[i] == target ) return i;\n    }\n    return -1;\n}\n</pre>\n\n<p>Реализация последовательного поиска на C++:</p>\n\n<pre class=\"brush: cpp;\">\n#include &lt;iostream&gt;\nusing namespace std;\n\nint SequentalSearch( int*, int, int );\nint main() {\n    int *mas, n, i, target;\n    cin &gt;&gt; n;\n    mas = new int[n];\n    for ( i = 0; i &lt; n; i++ ) cin &gt;&gt; mas[i];\n    cin &gt;&gt; target;\n    cout &lt;&lt; SequentalSearch(mas,n,target) &lt;&lt; endl;\n    return 0;\n}\n\nint SequentalSearch( int *mas, int n, int target) {\n    int i;\n    for ( i = 0; i &lt; n; i++ ) {\n        if ( mas[i]==target ) return i;\n    }\n    return -1;\n}\n</pre>\n\n<p>Реализация последовательного поиска на Java:</p>\n\n<pre class=\"brush: java;\">\nimport java.io.*;\nimport java.util.*;\n \nclass SequentalSearch { \n    public static void main(String[] args) {  \n        Locale.setDefault(Locale.ENGLISH);\n        Scanner in = new Scanner(System.in);\n        PrintWriter out = new PrintWriter(System.out);   \n        int mas[], n, i, target;\n        n = in.nextInt();\n        mas = new int[n];\n        for ( i = 0; i &lt; n; i++ ) mas[i] = in.nextInt();\n        target = in.nextInt();\n        out.println( SequentalSearch(mas,n,target) );\n        out.flush();\n    }\n    public static int SequentalSearch( int mas[], int n, int target) {\n        int i;\n        for ( i = 0; i &lt; n; i++ ) {\n            if ( mas[i] == target ) return i;\n        }\n        return -1;\n    }\n}\n</pre>\n\n<p>Лекцию подготовили: <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a> и <a href=\"[[constant name=portal_url]]users/show/?id=2\">Александр Проскуряков</a></p>\n\n<p>Реализации: С/С++/Java - <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a></p>\n\n<p>Pascal - <a href=\"[[constant name=portal_url]]users/show/?id=3\">Сабина Исаева</a></p>\n', '2014-08-16 13:52:15', 0, 1, 1),
(35, 'az', 'Binar axtarış', 109, 'binar-axtarish', '<p>Hesab edək ki bizə sıralanmış <b>N</b> ünsürdən ibarət olan siyahi verilib. Məqsədi ünsürü siyaxıda <b>i</b> göstəricisi ilə olan təsadüfi ünsür ilə müqaisə edək. Üc hala nəzər edək:</p>\n', '<p>Hesab edək ki bizə sıralanmış <b>N</b> ünsürdən ibarət olan siyahi verilib. Məqsədi ünsürü siyaxıda <b>i</b> göstəricisi ilə olan təsadüfi ünsür ilə müqaisə edək. Üc hala nəzər edək:</p>\n\n\n<ol>\n	<li>Məqsədi ünsür <b>i</b> göstəricisi olan ünsür ilə bərabərdi.</li>\n	<li>Məqsədi ünsür <b>i</b> göstəricisi olan ünsürdan böyükdür.</li>\n	<li>Məqsədi ünsür <b>i</b> göstəricisi olan ünsürdan kiçikdir.</li>\n</ol>\n\n<p>Siyahının siralanmış olduğuna əsasən 2-ci və 3-cü halda biz <b>[0,i]</b> və ya <b>[i,N-1]</b> kəsirində olan ünsürləri nəzərdən çixarıb, və həmən algoritmi siyahinin qalan hissəsinə rekursiv olaraq tətbiq edə bilərik. Alqoritmin optimallığını nəzərə alaraq siyahı bölünən zaman alınmış hissələrin ünsürlarının sayı təhminən eyni olmalıdır (ən çoxu 1 ünsür fərqlənə bilər). Beləliklə tez-tez <b>i</b> bərabər olunur <b>N/2</b>. Bu logorifmik axtarış murəkkəbliyini təmin edir, elə ki <b>N</b> həmişə bu şərtlərə cavab verir: <b>2<sup>K</sup> ≤ N &lt; 2<sup>K+1</sup></b>. Aydındı ki, <b>2<sup>K</sup></b> ünsürlü olan siyahıda ən çoxu <b>K+1</b> müqaisə apara bilərik. Burdan isə <b>N</b> ünsürlü siyahıda <b>log<sub>2</sub>N+1</b> müqaisə aparılır. Beləliklə binar axtarış algoritmin mürəkkəbliyi <b>O(log{N})</b>.</p>\n\n<p>Alqoritmi sadə anlamaq üçün bu funksiyanı daxil edək:</p>\n\n<p align=\"center\"><img src=\"[[constant name=portal_url]]materials/algo/article/4_1.png\" /></p>\n\n<p>Bu funksiya keçid düyməsi rolunu oynayır. <b>switch</b> komandasını istifadə edərək biz <b>compare(mas[middle],target)</b> funksiyasının nəticəsinə görə 3 haldan birinə baxa bilərik, burada <b>middle</b> - orta üstürünün göstəricisidi.</p>\n\n<p>Pascal dilində binar axtarışının həyata keçirilməsi:</p>\n\n<pre class=\"brush: pascal;\">\nProgram Binary_Search;\ntype intarray = array[1..1000] of integer;\nvar    \n    mas : intarray;    \n    n, i, target : integer;\n\nfunction compare(x, y : integer) : integer;\nbegin    \n    if ( x &lt; y ) then compare := -1 \n    else if ( x = y ) then compare := 0 \n    else compare := 1;\nend;\n\nfunction BinarySearch(mas : intarray; n, target : integer ) : integer;\nvar    \n    start, finish, middle : integer;\nbegin    \n    start := 1;    \n    finish := n;    \n    while ( start &lt;= finish ) do    \n    begin        \n        middle := ( start + finish ) div 2;        \n        case (compare(mas[middle], target)) of            \n            -1 : start := middle + 1;            \n            0 : begin BinarySearch := middle; break; end;            \n            1 : finish := middle - 1;        \n        end;    \n    end;\nend;\n\nbegin    \n    readln(n);    \n    for i := 1 to n do    \n        read(mas[i]);    \n    readln(target);    \n    writeln(BinarySearch(mas, n,target) );\nend.\n</pre>\n\n<p>C dilində binar axtarışının həyata keçirilməsi:</p>\n\n<pre class=\"brush: c;\">\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n\nint BinarySearch( int*, int, int );\nint compare ( int , int );\n\nint main(void) \n{    \n    int *mas, n, i, target;\n    scanf( \"%d\", &amp;n );    \n    mas = ( int* ) malloc(n * sizeof(int));    \n    for ( i = 0; i &lt; n; i++ ) scanf( \"%d\", &amp;mas[i] );    \n    scanf( \"%d\", &amp;target );    \n    printf(\"%d\\n\", BinarySearch(mas,n,target ) );    \n    return 0;\n}\n\nint BinarySearch( int *mas, int n, int target ) \n{    \n    int start = 0, finish = n-1, middle;    \n    while ( start &lt;= finish ) \n    {       \n        middle = ( start + finish ) / 2;        \n		switch ( compare(mas[middle],target) ) \n        {            \n            case -1: start = middle + 1; break;            \n            case 0: return middle;            \n            case 1: finish = middle - 1; break;        \n        }    \n    }    \n    return -1;\n}\n\nint compare ( int x, int y ) \n{    \n    if ( x &lt; y ) return -1;    \n    if ( x == y ) return 0;    \n    return 1;\n}\n</pre>\n\n<p>C++ dilində binar axtarışının həyata keçirilməsi:</p>\n\n<pre class=\"brush: cpp;\">\n#include &lt;iostream&gt;\nusing namespace std;\n\nint BinarySearch( int*, int, int );\nint compare ( int , int );\n\nint main() \n{    \n    int *mas, n, i, target;    \n    cin &gt;&gt; n;    \n    mas = new int[n];    \n    for ( i = 0; i &lt; n; i++ ) cin &gt;&gt; mas[i];    \n    cin &gt;&gt; target;   \n    cout &lt;&lt; BinarySearch(mas,n,target) &lt;&lt; endl;    \n    return 0;\n}\n\nint BinarySearch( int *mas, int n, int target ) \n{    \n    int start = 0, finish = n-1, middle;    \n    while ( start &lt;= finish ) \n    {        \n        middle = ( start + finish ) / 2;       \n        switch ( compare(mas[middle],target) ) \n        {            \n            case -1: start = middle + 1; break;            \n            case 0: return middle;            \n            case 1: finish = middle - 1; break;        \n        }    \n    }    \n    return -1;\n}\n\nint compare ( int x, int y ) \n{    \n    if ( x &lt; y ) return -1;    \n    if ( x == y ) return 0;    \n    return 1;\n}\n</pre>\n\n<p>Java dilində binar axtarışının həyata keçirilməsi:</p>\n\n<pre class=\"brush: java;\">\nimport java.io.*;\nimport java.util.*;\n\nclass BinarySearch \n{     \n    public static void main(String[] args) \n    {          \n        Locale.setDefault(Locale.ENGLISH);\n        Scanner in = new Scanner(System.in);        \n        PrintWriter out = new PrintWriter(System.out);          \n        int mas[], n, i, target;        \n        n = in.nextInt();        \n        mas = new int[n];       \n        for ( i = 0; i &lt; n; i++ ) mas[i] = in.nextInt();        \n        target = in.nextInt();        \n        out.println( BinarySearch(mas,n,target) );        \n        out.flush();   \n    }   \n    public static int BinarySearch( int mas[], int n, int target ) \n    {	    \n        int start = 0, finish = n-1, middle;        \n        while ( start &lt;= finish ) \n        {            \n            middle = ( start + finish ) / 2;            \n            switch ( compare(mas[middle],target) ) \n            {                \n                case -1: start = middle + 1; break;                \n                case 0: return middle;                \n                case 1: finish = middle - 1; break;            \n            }        \n        }        \n        return -1;    \n    }    \n    public static int compare ( int x, int y ) \n    {        \n        if ( x &lt; y ) return -1;        \n        if ( x == y ) return 0;        \n        return 1;    \n    }\n}\n</pre>\n\n<p>Mühazirəni hazırlayanlar: <a href=\"[[constant name=portal_url]]users/show/?id=1\">Əli Vəliyev</a> və <a href=\"[[constant name=portal_url]]users/show/?id=2\">Aleksandr Proskuryakov</a></p>\n\n<p>Programların həyata keçirilməsi: С/С++/Java - <a href=\"[[constant name=portal_url]]users/show/?id=1\">Əli Vəliyev</a></p>\n\n<p>Pascal - <a href=\"[[constant name=portal_url]]users/show/?id=3\">İsayeva Səbinə</a></p>\n\n<p>Tərcümə: <a href=\"[[constant name=portal_url]]users/show/?id=1\">Əli Vəliyev</a></p>\n', '2014-08-16 14:13:28', 0, 1, 1);
INSERT INTO `articles` (`id`, `language`, `title`, `category`, `slug`, `short`, `content`, `date`, `cover_image`, `author`, `visibility`) VALUES
(36, 'az', 'Giriş və graf nəzəriyyəsi əsas anlayışlar', 110, 'girish-ve-graf-nezeriyyesi-esas-anlayishlar', '<p>İnternetdə qraflar nəzəriyyəsi üzrə (görə) kitabların böyük miqdarı mövcuddur. Və əgər onların ümumi kəsişməsini götürməksə, ona bütün axan nəticələri yazıb qurtarmaqsa, onda o böyüyü yaratmaq olar, hansını ki, oxuyub hələ (daha) bir yığın sual (məsələ) qalacaq. Buna görə Sizə \"Qraflar nəzəriyyəsi\" üzrə (görə) kiçik kitabçadan kəsməni (kəsiyi) təqdim edirik. Biz nadir hallarda şəxsi müəllifliyin bu mövzusuna mühazirələri çıxardacağıq, çünki bunda heç bir məna görmürük. Axı hamı (hər şey) ki, biz Sizə çatdırmaq istəyirik, hörmətli oxucular, artıq başqa sözlə çox kitablarda təsvir edilmişdir. Bu mövzuya məsələlərin qərarı (həlli) üçün əvvəlcə zadəganlıq təyinlərin və xüsusiyyətlərin yetərli miqdarı lazımdır, və (amma) bizdən sonra alqoritmlərin özlərinin öyrənilməsinə keçəcəyik. Qrafların xüsusiyyətlərinin biliyi daha az əhəmiyyətli deyil, çünki bəzən məsələlər düşür (rast gəlir), harada sadəcə düsturdan istifadə etmək lazımdır, və (amma) dərinliyə qrafı keçməmək və ya ümumiyyətlə yaddaşda onu necəsə saxlamaq.</p>\n', '<p>İnternetdə qraflar nəzəriyyəsi üzrə (görə) kitabların böyük miqdarı mövcuddur. Və əgər onların ümumi kəsişməsini götürməksə, ona bütün axan nəticələri yazıb qurtarmaqsa, onda o böyüyü yaratmaq olar, hansını ki, oxuyub hələ (daha) bir yığın sual (məsələ) qalacaq. Buna görə Sizə \"Qraflar nəzəriyyəsi\" üzrə (görə) kiçik kitabçadan kəsməni (kəsiyi) təqdim edirik. Biz nadir hallarda şəxsi müəllifliyin bu mövzusuna mühazirələri çıxardacağıq, çünki bunda heç bir məna görmürük. Axı hamı (hər şey) ki, biz Sizə çatdırmaq istəyirik, hörmətli oxucular, artıq başqa sözlə çox kitablarda təsvir edilmişdir. Bu mövzuya məsələlərin qərarı (həlli) üçün əvvəlcə zadəganlıq təyinlərin və xüsusiyyətlərin yetərli miqdarı lazımdır, və (amma) bizdən sonra alqoritmlərin özlərinin öyrənilməsinə keçəcəyik. Qrafların xüsusiyyətlərinin biliyi daha az əhəmiyyətli deyil, çünki bəzən məsələlər düşür (rast gəlir), harada sadəcə düsturdan istifadə etmək lazımdır, və (amma) dərinliyə qrafı keçməmək və ya ümumiyyətlə yaddaşda onu necəsə saxlamaq.</p>\n\n\n<p>Biz hansısa bir konkret mühazirələrdə dayanmayacağıq, bir halda ki, (çünki,) necə artıq yuxarı, çox zaman bu müxtəlif dillərdə yazılmış eyni fikir deyilmişdi. Və ki, oxucu ifadənin eyni stilinə öyrəşməsin, biz müxtəlif mənbələrdən mühazirələri çıxardacağıq. Ancaq biz onlar belə tikməyə çalışacağıq ki, bu fərq heç vaxt özünü göstərməsin.</p>\n\n<h3>Bir az tarix və predmet haqqında...</h3>\n\n<p>Qraflar nəzəriyyəsi diskret riyaziyyatın bölmələrindən biridir, hansı ki, onların elementlərinin arasında verilmiş münasibətlərlə (əlaqələrlə) son və ya hesab çoxluqlarının xüsusiyyətlərini tədqiq edir. Obyektlərin öyrənilməsinə həndəsi yanaşma bu nəzəriyyənin xüsusiyyətidir.</p>\n\n<p>İlk dəfə \"qraf\" anlayışı macar riyaziyyatçısı Deneş Кëниг 1936-cı ildə daxil etdi. Ancaq qraflar nəzəriyyəsi üzrə (görə) birinci iş hələ (daha) 1736-cı ildə Leonard Eyler tərəfindən yazılmışdı, hansında ki, o \"məsələni haqqında Кëнигсбергских körpülər\" həll etdi. Bu məsələnin mahiyyəti növbətidən ibarətdir. Şəkildə. 1 şəhərin mərkəzi hissəsinin sxemi Кëнигсберг təqdim edilmişdir (təsəvvür edilmişdir) (hal-hazırda Kalininqrad), hansı ki, iki çayın qırağı, onda iki ada və yeddi birləşdirən onların körpüsü daxil edir (qoşur). Hamını (hər şeyi) qurunun dörd hissəsi keçmək tələb olunur, bir dəfə hər körpü üzrə (görə) keçib, və ilk nöqtəyə qayıtmaq. Sonra biz bu məsələnin qərarına (həllinə) baxacağıq.</p>\n\n<p align=\"center\"><img src=\"/images/algo/5_1.png\" /></p>\n\n<p>Müasir qraflar nəzəriyyəsi müxtəlif təbiətin obyektlərinin arasında müxtəlif sistemlərin və münasibətlərin (əlaqələrin) struktur xüsusiyyətlərinin modelləşdirilməsi üçün xüsusi (istisna) rahat aparatı verir. Buna görə o geniş istifadə olunur necə özündə riyaziyyata, həm də elmin, texnikanın və praktik fəaliyyətin ən müxtəlif sahələrində (ərazilərində) onun əlavələri (proqramları). Xüsusi halda, qraflar nəzəriyyəsi informatikada və proqramlaşdırmada öz tətbiqini tapır, kimyalar, iqtisadiyyata, logistikaya, rabitə və nəqliyyat sistemlərində, sxemotexnike.</p>\n\n<h3>Əsas anlayışlar və təyinlər</h3>\n\n<p>Пусть S &nbsp;– &nbsp;непустое &nbsp;конечное &nbsp;множество, &nbsp; V(2) &nbsp;– &nbsp;множество &nbsp; всех &nbsp;его двухэлементных&nbsp;подмножеств.</p>\n\n<p><em><strong>Определение &nbsp;1.1.</strong></em> &nbsp;Псевдографом &nbsp;(или просто графом) G &nbsp;называется &nbsp;пара множеств (S,U), где U -&nbsp;произвольное&nbsp;подмножество множества V(2) . При этом пишут G = (S,U).</p>\n\n<p><em><strong>Определение &nbsp;1.2.</strong></em> &nbsp;Пусть G &nbsp;= &nbsp;(S,U) &nbsp;– &nbsp;псевдограф. &nbsp;Элементы &nbsp;множества &nbsp;S называются вершинами&nbsp;графа G, а элементы множества &nbsp;U – его ребрами.&nbsp;</p>\n\n<p><em><strong>Определение 1.3.</strong></em> Граф G = (S,U) называется пустым&nbsp;или нуль-графом, если&nbsp;U = ∅.</p>\n\n<p><em><strong>Определение 1.4.</strong></em> Число вершин графа G = (S,U) называется его порядком.&nbsp;Если порядок графа равен n, то пишут |G| = n.</p>\n\n<p>Двухэлементное подмножество &nbsp;множества S (ребро), &nbsp;принадлежащее U и&nbsp;состоящее из элементов x и y будем&nbsp;обозначать через (x, y).&nbsp;В общем случае множество U может содержать пары с одинаковыми элементами вида (x, x) и одинаковые&nbsp;пары.</p>\n\n<p><em><strong>Определение 1.5.</strong></em> Ребра вида (x, x) называются петлями.</p>\n\n<p><em><strong>Определение 1.6.</strong></em> Одинаковые пары из множества U называются кратными&nbsp;(или параллельными) ребрами.</p>\n\n<p>Таким образом, псевдограф может содержать петли и кратные ребра. В этом смысле псевдографы еще&nbsp;называются графами с кратными ребрами и петлями.</p>\n\n<p><em><strong>Определение &nbsp;1.7.</strong></em> &nbsp;Псевдограф &nbsp;без &nbsp;петель &nbsp;называется &nbsp;мультиграфом &nbsp;(или графом с кратными&nbsp;ребрами).</p>\n\n<p><em><strong>Определение &nbsp; 1.8.</strong></em> &nbsp; Мультиграф &nbsp; без &nbsp;кратных &nbsp; ребер &nbsp;называется &nbsp;простым&nbsp;графом.</p>\n\n<p>Таким образом, простой граф не содержит петель и кратных ребер.</p>\n\n<p>Графы имеют наглядную &nbsp;графическую &nbsp;интерпретацию в виде диаграмм, состоящих из точек и линий,&nbsp;соединяющих &nbsp;некоторые из этих точек. Точки соответствуют вершинам графа, а линии &nbsp;– его ребрам.&nbsp;При этом форма и длина линий значения не имеют. Важно лишь, что две данные точки соединены или не&nbsp;соединены линией.</p>\n\n<p><span style=\"line-height:1.6em\"><em><strong>Пример 1.1.</strong></em> Указать какие из графов, диаграммы которых изображены на&nbsp;</span><span style=\"line-height:1.6em\">рис. 2 являются псевдографами, мультиграфами, простыми графами.</span></p>\n\n<p align=\"center\"><img src=\"/images/algo/5_2.png\" /></p>\n\n<p><em><strong>Решение.</strong></em> &nbsp; Все &nbsp;графы &nbsp; являются псевдографами, &nbsp; графы &nbsp; G1, &nbsp;G3, &nbsp;G4, &nbsp;G5 –&nbsp;мультиграфами, графы G1, G4, G5 &nbsp;-&nbsp;простыми графами. &nbsp;</p>\n\n<p><em><strong>Определение 1.9. </strong></em>&nbsp; &nbsp;Граф называется <strong>неориентированным</strong> (кратко &nbsp;–&nbsp;неорграфом), если пары в множестве U являются неупорядоченными.</p>\n\n<p>Если &nbsp;(x, y) &nbsp; – &nbsp; неупорядоченная &nbsp; пара, &nbsp; то &nbsp;ребро (x, y) называется&nbsp;неориентированным, а вершины x &nbsp;и y называются&nbsp;концами&nbsp;неориентированного ребра (x, y).</p>\n\n<p><em><strong>Определение 1.10.</strong></em> Граф называется <strong>ориентированным</strong> (кратко – орграфом),&nbsp;если пары в множестве U являются упорядоченными.</p>\n\n<p><em><strong>Определение 1.11.</strong></em>&nbsp;Ребра орграфа называются <strong>дугами</strong> (или&nbsp;ориентированными ребрами).</p>\n\n<p>Вершина x дуги (x, y) называется ее началом, &nbsp;а вершина y – ее концом. В&nbsp;этом случае говорят, что дуга (x, y) исходит из вершины x и входит в вершину y.&nbsp;На диаграммах орграфов направления дуг отмечаются стрелками, которые примыкают к их концам.</p>\n\n<p><em><strong>Замечание 1.1.</strong></em> Неориентированное ребро (x, y) равносильно двум&nbsp;противоположно направленным дугам (x, y) и (y, x). Поэтому неориентированный граф можно&nbsp;рассматривать как ориентированный граф, который вместе с каждой дугой (x, y) содержит и дугу (y, x)&nbsp;противоположного направления.</p>\n\n<p>Условимся вершины графа обозначать буквами x, y, z (без индексов или с индексами), а ребра и дуги –&nbsp;буквами v, u, w (без индексов или с индексами).&nbsp;Рассмотрим ряд понятий и определений для неориентированных &nbsp;и&nbsp;ориентированных графов. &nbsp;При этом, если не будет оговорено особо, те же понятия и определения&nbsp;переносятся без изменений на неориентированные &nbsp;и ориентированные псевдографы.</p>\n\n<p><em><strong>Определение 1.12.</strong></em> Два ребра графа называются <strong>смежными</strong>, если они имеют общий конец.</p>\n\n<p><em><strong>Определение 1.13.</strong></em> Вершина x и ребро u графа называются <strong>инцидентными</strong>,&nbsp;если x является концом ребра u, и неинцидентными в противном случае.</p>\n\n<p><em><strong>Определение 1.14.</strong></em> Две вершины графа называются <strong>смежными</strong>, если существует инцидентное им ребро.</p>\n\n<p><em><strong>Определение 1.15.</strong></em> Число ребер (дуг) графа (орграфа) G, инцидентных данной вершине x<sub>i</sub> называется&nbsp;<strong>степенью (валентностью) вершины</strong> x<sub>i</sub> и обозначается через deg (x<sub>i</sub>) (от англ. degree – степень).</p>\n\n<p><em><strong>Определение 1.16.</strong></em> Вершина графа называется <strong>изолированной</strong>, &nbsp;если ее степень&nbsp;равна нулю.</p>\n\n<p><em><strong>Определение 1.17.</strong></em> Вершина графа называется <strong>висячей</strong>, &nbsp;а если ее степень равна единице.</p>\n\n<p><em><strong>Замечание 1.2.</strong></em> В случае неориентированного псевдографа обычно считается, что вклад каждой петли,&nbsp;инцидентной некоторой вершине x, в ее степень P(x) равен 2, в то время как вклад любого другого&nbsp;ребра, инцидентного вершине x равен 1.</p>\n\n<p><em><strong>Определение 1.18.</strong></em> Полустепенью исхода (захода) вершины xi орграфа называется число deg<sup>+</sup>(x<sub>i</sub>) (deg<sup>–</sup>(x<sub>i</sub>)) его дуг, исходящих из вершины x<sub>i</sub> (заходящих в вершину x<sub>i</sub>).&nbsp;Для орграфа deg (x<sub>i</sub>) = deg<sup>+</sup>(x<sub>i</sub>) + deg<sup>–</sup>(x<sub>i</sub>).</p>\n\n<p><em><strong>Замечание 1.3.</strong></em> В случае ориентированного псевдографа вклад каждой петли,&nbsp;инцидентной некоторой вершине x, равен 1, как в deg<sup>+</sup>(x), так и в deg<sup>–</sup>(x).</p>\n\n<p><em><strong>Определение 1.19.</strong></em> Неориентированный простой граф, &nbsp;в котором любые две&nbsp;различные &nbsp;вершины &nbsp;смежны, называется&nbsp;<strong>полным</strong>. Полный граф &nbsp;порядка &nbsp;n&nbsp;обозначается через K<sub>n</sub>.</p>\n\n<p><em><strong>Определение &nbsp;1.20.</strong></em> &nbsp;Неориентированный &nbsp;граф &nbsp;называется &nbsp;<strong>двудольным</strong>, если&nbsp;существует такое разбиение множества его вершин &nbsp;на две части (доли), что концы каждого ребра&nbsp;принадлежат разным частям.</p>\n\n<p><em><strong>Определение 1.21.</strong></em> &nbsp;Двудольный граф, любые две вершины которого, входящие&nbsp;в разные доли смежны, &nbsp;называется <strong>полным двудольным</strong>. Полный двудольный граф, доли которого состоят&nbsp;из p и q вершин, обозначается символом K<sub>p,q</sub>.</p>\n\n<p>Mənbə: A.V. Çerednikova, İ.V. Zemlyakova, qraflar nəzəriyyəsinə Müqəddimə (Daxil etmə), Kostrama, KQTU, 2011</p>\n', '2014-08-16 14:15:11', 0, 1, 1),
(37, 'ru', 'Что необходимо знать о составлении алгоритмов для решения задач?', 108, 'что-необходимо-знать-о-составлении-алгоритмов-для-решения-задач', '<p>В современном мире профессия программиста является одной из востребованных.</p>\n\n<p><span style=\"line-height:1.6em\">Но что же именно подразумевает это слово-«программист»? Человек, который целыми днями печатает &nbsp;бессмысленный машинный код? А почему, собственно, &nbsp;бессмысленный? Может он, все таки, что-то значит?&nbsp;</span></p>\n', '<p>В современном мире профессия программиста является одной из востребованных.</p>\n\n<p><span style=\"line-height:1.6em\">Но что же именно подразумевает это слово-«программист»? Человек, который целыми днями печатает &nbsp;бессмысленный машинный код? А почему, собственно, &nbsp;бессмысленный? Может он, все таки, что-то значит?&nbsp;</span></p>\n\n<p><span style=\"line-height:1.6em\">Конечно же, помимо широкой востребованности, это, еще и одна из самых трудоемких профессий, требующее алгоритмический склад ума.</span></p>\n\n<p><span style=\"line-height:1.6em\">Что же такое «алгоритм»?</span></p>\n\n<p>Ответ на этот вопрос можно прочитать, например, в&nbsp;<a href=\"http://ru.wikipedia.org/wiki/%D0%90%D0%BB%D0%B3%D0%BE%D1%80%D0%B8%D1%82%D0%BC\">Википедии</a>.</p>\n\n<blockquote>\n<p><em style=\"line-height:1.6em\">Алгори́тм — набор инструкций, описывающих порядок действий исполнителя для достижения результата решения задачи за конечное число действий.</em></p>\n</blockquote>\n\n<p>&nbsp;Нет необходимости долго разбираться в статье, &nbsp;чтобы понять, что программист, в первую очередь, должен хорошо разбираться в алгоритмах. На нашем сайте присутствует раздел &nbsp;«<a href=\"http://studyprog.com/code/\">Кодинг</a>». По большей части, этот раздел будет в помощь, так называемым \"кодерам\". Кодером в народе принято называть того, кто реализует готовые алгоритмы. Наш ресурс полезен как для разработчиков алгоритмов, так и для кодеров.</p>\n\n<p><span style=\"line-height:1.6em\">А теперь &nbsp;рассмотрим &nbsp;весь процесс грамотного составления алгоритма.</span></p>\n\n<ol>\n	<li>Внимательно изучить поставленную перед собой задачу. Обдумать, что должно подаваться на вход программы, и &nbsp;что она должна выводить.</li>\n	<li>Составить алгоритм решения задачи&nbsp; напрямую.</li>\n	<li>Максимально оптимизировать решение так, чтобы оно выполняло как можно меньше операций. Минимизировать объем памяти используемый структурами данных.</li>\n	<li>После того как мы получили необходимый алгоритм, время его реализовать. Необходимо разбить алгоритм на максимальное количество частей, реализуемые &nbsp;функциями или процедурами таким образом, что каждую подфункцию (подпроцедуру) уже невозможно было поделить на более мелкие.&nbsp;И уже из главной функции создавать суперпозиции этих функций.</li>\n	<li>&nbsp;Реализовать каждую функцию как отдельную программу. Тщательно проверьте, чтобы каждая функция выполняла предписанный ей алгоритм.</li>\n</ol>\n\n<p>Использование этих правил позволит вам грамотно реализовывать придуманный алгоритм.&nbsp;Ну, а если у вас что-то не получится, вы хорошо знаете, куда следует обращаться.</p>\n\n<p>Задавайте ваши вопросы на сайте интеллектуального сообщества&nbsp;<a href=\"http://qformat.net/blog/ocode/\">QFormat</a>, а также в нашей группе на <a href=\"http://www.facebook.com/groups/studyprog/\">Facebook</a>. До новых встреч, дорогие STUDYPROGраммисты!</p>', '2014-07-04 03:28:43', 0, 1, 1),
(38, 'ru', 'Сложности алгоритмов', 108, 'сложности-алгоритмов', '<p>Когда перед нами стоит условие задачи, наша главная цель придумать такой алгоритм, чтобы для входных данных из заданного диапазона программа выдавала верный ответ для всех тестов и укладывать в заданные лимиты времени и памяти.</p>', '<p>Когда перед нами стоит условие задачи, наша главная цель придумать такой алгоритм, чтобы для входных данных из заданного диапазона программа выдавала верный ответ для всех тестов и укладывать в заданные лимиты времени и памяти.</p>\n\n<p><strong><em>Определение 1.</em></strong> Операция называется элементарной, если в алгоритме её можно представить в виде некоторой единицы действия. Например: проверка условия, арифметическая операция, считывание данных и т.п. считаются элементарными операциями.</p>\n\n<p>Пусть <em><strong>f </strong></em>и <em><strong>g</strong></em> две функции (для простоты отображающие действительные числа в действительные). Говорят, что <em><strong>f</strong></em> является O(<em><strong>g</strong></em>) &nbsp;(читается &quot;о-большое от <em><strong>g</strong></em>&quot;), если функция <em><strong>f</strong></em> растёт не быстрее, чем функция <strong><em>g</em></strong>.</p>\n\n<p>Пусть <em><strong>f</strong></em> и <em><strong>g</strong></em> две функции (для простоты отображающие действительные числа в действительные). Говорят, что <em><strong>g</strong></em> является &Omega;(<strong><em>f</em></strong>) (читается &quot;омега-большое от <em><strong>f</strong></em>&quot;), если функция <em><strong>f</strong></em> есть O(<strong><em>g</em></strong>)</p>\n\n<p>Работу алгоритма при вводе конкретных входных данных назовём экспериментом. В основном полагается, что количество экспериментов стремится к бесконечности с ростом входных данных.&nbsp;</p>\n\n<p>Пусть последовательность результатов работы времени экстпериментов задаёт некоторую функцию <em><strong>f</strong></em> на вещественной оси. Будем говорить, что алгоритм работает за время O(<em><strong>g</strong></em>), если существует такая функция <em><strong>g</strong></em>, что <em><strong>f</strong></em> есть O(<em><strong>g</strong></em>) и любая другая функция <em><strong>h</strong></em> являющаяся O(<strong><em>g</em></strong>) не является &Omega;(<em><strong>f</strong></em>).&nbsp;</p>\n\n<p><strong><em>Определение 2.</em></strong> Сложностью алгоритма называется функция <strong><em>f</em></strong>, такая что алгоритм выполняет O(<strong><em>f</em></strong>) элементарных операций при стремлении входных данныъ к бесконечности.</p>\n\n<p>Лекцию подготовил: <a href=\"http://studyprog.com/ru/profile/show/?username=admin\">Али Велиев</a>.</p>\n\n<p>Используемые источники: <a href=\"http://www.wikipedia.org/\">Википедия</a>, <a href=\"http://www.intuit.ru/\">Интернет-университет &quot;Интуит&quot;</a>,&nbsp;Макконнелл Дж. - Основы современных алгоритмов.</p>\n', '2014-08-16 13:50:44', 0, 1, 1),
(39, 'ru', 'Введение в раздел и последовательный поиск', 109, 'введение-в-раздел-и-последовательный-поиск', '<p>Все последующие алгоритмы сортировок служат для решения одной задачи: отсортировать массив данных. На обучении в смысле \"данные\" мы будем понимать целые числа. Однако реализация будет идти в общем случае с использованием дополнительной функции <b>int compare()</b>.', '<p>Все последующие алгоритмы сортировок служат для решения одной задачи: отсортировать массив данных. На обучении в смысле \"данные\" мы будем понимать целые числа. Однако реализация будет идти в общем случае с использованием дополнительной функции <b>int compare()</b>. В таком случае мы сможем сортировать не только в порядке возрастания, но и в порядке убавания, а также по специальному критерию (например дав определение, что число меньше если меньше число его единиц, независимо от числа десятков и других разрядов). Также будет использована отдельная функция <b>void swap()</b>, которая позволит параллельно с сортировкой одного массива сортировать второй (например, сортировка координат точек по координате x). Хотя это и уменьшает скорость работы (многократный вызов дополнительных функций), но помогает легче запомнить алгоритм и если нужно и код.</p>\n\n<p>Часто возникает надобность найти какой-либо заданный элемент в заданном списке. Этот заданый элемент называется целевым. Список элементов по умолчанию считается неотсортированным. Мы также поговорим об алгоритме последовательного поиска в отсортированном списке.</p>\n\n<p>Пусть у нас имеется последовательность из N элементов. Идея алгоритма состоит в последовательном обходе элементов и сравнении их с целевым. Очевидно, что максимальное число сравнений может быть N, так как два наихудших случая алгоритма (в последовательности нет целевого элемента или целевой элемент последний в списке) требует ровно N сравнений. Если бы сравнений было бы больше N, это значило бы что существует элемент, который участвовал в сравнении более одного раза. В соображениях минимальности операций для наихудшего случая возникает противоречие. Время работы последовательного поиска O(N), так как при сравнении также учитывается, что не всякий тип данных требует для сравнения одну операцию (например 64-битные числа на 32-битной машине).</p>\n\n<p>Следующие реализации обходят массив целых чисел, сравнивают каждый элемент с целевым элементов <b>target</b> и возвращают индекс элемента. Если целевой элемент не найден, то возвращается несуществующее значение индекса.</p>\n\n<p>Реализация последовательного поиска на Pascal:</p>\n\n<pre class=\"brush: pascal;\">\nProgram Sequental_Search;\ntype intarray = array[1..100] of integer;\nvar \n    mas : intarray;\n    n, i, target : integer;\n\nfunction SequentalSearch(mas : intarray; n, target : integer ) : integer;\nvar\n    i : integer;\nbegin\n    SequentalSearch := 0;\n    for i := 1 to n do\n    if ( mas[i] = target ) then SequentalSearch := i;\nend;\n\nbegin\n    readln(n);\n    for i:=1 to n do\n    read(mas[i]);\n    read(target);\n    writeln(SequentalSearch(mas,n,target));\nend.\n</pre>\n\n<p>Реализация последовательного поиска на C:</p>\n\n<pre class=\"brush: c;\">\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n\nint SequentalSearch( int*, int, int );\nint main(void) {\n    int *mas, n, i, target;\n    scanf( \"%d\", &amp;n );\n    mas = ( int* ) malloc(n * sizeof(int));\n    for ( i = 0; i &lt; n; i++ ) scanf( \"%d\", &amp;mas[i] );\n    scanf( \"%d\", &amp;target );\n    printf(\"%d\n\", SequentalSearch(mas,n,target ) );\n    return 0;\n}\n\nint SequentalSearch( int *mas, int n, int target) {\n    int i;\n    for ( i = 0; i &lt; n; i++ ) {\n        if ( mas[i] == target ) return i;\n    }\n    return -1;\n}\n</pre>\n\n<p>Реализация последовательного поиска на C++:</p>\n\n<pre class=\"brush: cpp;\">\n#include &lt;iostream&gt;\nusing namespace std;\n\nint SequentalSearch( int*, int, int );\nint main() {\n    int *mas, n, i, target;\n    cin &gt;&gt; n;\n    mas = new int[n];\n    for ( i = 0; i &lt; n; i++ ) cin &gt;&gt; mas[i];\n    cin &gt;&gt; target;\n    cout &lt;&lt; SequentalSearch(mas,n,target) &lt;&lt; endl;\n    return 0;\n}\n\nint SequentalSearch( int *mas, int n, int target) {\n    int i;\n    for ( i = 0; i &lt; n; i++ ) {\n        if ( mas[i]==target ) return i;\n    }\n    return -1;\n}\n</pre>\n\n<p>Реализация последовательного поиска на Java:</p>\n\n<pre class=\"brush: java;\">\nimport java.io.*;\nimport java.util.*;\n \nclass SequentalSearch { \n    public static void main(String[] args) {  \n        Locale.setDefault(Locale.ENGLISH);\n        Scanner in = new Scanner(System.in);\n        PrintWriter out = new PrintWriter(System.out);   \n        int mas[], n, i, target;\n        n = in.nextInt();\n        mas = new int[n];\n        for ( i = 0; i &lt; n; i++ ) mas[i] = in.nextInt();\n        target = in.nextInt();\n        out.println( SequentalSearch(mas,n,target) );\n        out.flush();\n    }\n    public static int SequentalSearch( int mas[], int n, int target) {\n        int i;\n        for ( i = 0; i &lt; n; i++ ) {\n            if ( mas[i] == target ) return i;\n        }\n        return -1;\n    }\n}\n</pre>\n\n<p>Лекцию подготовили: <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a> и <a href=\"[[constant name=portal_url]]users/show/?id=2\">Александр Проскуряков</a></p>\n\n<p>Реализации: С/С++/Java - <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a></p>\n\n<p>Pascal - <a href=\"[[constant name=portal_url]]users/show/?id=3\">Сабина Исаева</a></p>\n', '2014-08-16 13:52:15', 0, 1, 1),
(40, 'ru', 'Двоичный поиск', 109, 'двоичный-поиск', '<p>Пусть нам задан отсортированный в порядке неубывания список из <b>N</b> элементов. Сравним целевой элемент со случайным элементом из списка с индексом <b>i</b>. Рассмотрим три случая:</p>\n', '<p>Пусть нам задан отсортированный в порядке неубывания список из <b>N</b> элементов. Сравним целевой элемент со случайным элементом из списка с индексом <b>i</b>. Рассмотрим три случая:</p>\n\n\n<ol>\n	<li>Целевой элемент равен <b>i</b>-тому элементу.</li>\n	<li>Целевой элемент больше <b>i</b>-того элемента.</li>\n	<li>Целевой элемент меньше <b>i</b>-того элемента.</li>\n</ol>\n\n<p>Тогда исходя из отсортированности списка во втором и третьих случаях мы можем отбросить все элементы из отрезка <b>[0,i]</b> и <b>[i,N-1]</b> соответственно, и применить данную операцию рекурсивно ко второй половине списка. Также из соображений оптимальности алгоритма отброшенная и рассматриваемая часть списка должна содержать приблизительно одинаковое количество элементов (максимум различаться на 1 элемент). Поэтому очень часто полагают <b>i</b> равным <b>N/2</b>. Это обеспечивает логарифмическую сложность поиска, так как любое число <b>N</b> будет удовлетворять следующим условиям: <b>2<sup>K</sup> ≤ N &lt; 2<sup>K+1</sup></b>. Очевидно, что для списка из <b>2<sup>K</sup></b> элементов нужно будет произвести максимум <b>K+1</b> сравнений. Отсюда получаем что для списка из <b>N</b> элементов надо будет производить <b>log<sub>2</sub>N+1</b> сравнений. Следовательно, сложность алгоритма бинарного поиска <b>O(log{N})</b>.</p>\n\n<p>Для упрощения понимания алгоритма определим функцию:</p>\n\n<p align=\"center\"><img src=\"[[constant name=portal_url]]materials/algo/article/4_1.png\" /></p>\n\n<p>Эта функция будет играть роль переключателя. Используя команду <b>switch</b> мы сможем сделать одно из трёх доступных действий по полученному результату выполнения функции <b>compare(mas[middle],target)</b>, где <b>middle</b> - индекс среднего элемента.</p>\n\n<p>Реализация двоичного поиска на Pascal:</p>\n\n<pre class=\"brush: pascal;\">\nProgram Binary_Search;\ntype intarray = array[1..1000] of integer;\nvar    \n    mas : intarray;    \n    n, i, target : integer;\n\nfunction compare(x, y : integer) : integer;\nbegin    \n    if ( x &lt; y ) then compare := -1 \n    else if ( x = y ) then compare := 0 \n    else compare := 1;\nend;\n\nfunction BinarySearch(mas : intarray; n, target : integer ) : integer;\nvar    \n    start, finish, middle : integer;\nbegin    \n    start := 1;    \n    finish := n;    \n    while ( start &lt;= finish ) do    \n    begin        \n        middle := ( start + finish ) div 2;        \n        case (compare(mas[middle], target)) of            \n            -1 : start := middle + 1;            \n            0 : begin BinarySearch := middle; break; end;            \n            1 : finish := middle - 1;        \n        end;    \n    end;\nend;\n\nbegin    \n    readln(n);    \n    for i := 1 to n do    \n        read(mas[i]);    \n    readln(target);    \n    writeln(BinarySearch(mas, n,target) );\nend.\n</pre>\n\n<p>Реализация двоичного поиска на С:</p>\n\n<pre class=\"brush: c;\">\n#include &lt;stdio.h&gt;\n#include &lt;stdlib.h&gt;\n\nint BinarySearch( int*, int, int );\nint compare ( int , int );\n\nint main(void) \n{    \n    int *mas, n, i, target;\n    scanf( \"%d\", &amp;n );    \n    mas = ( int* ) malloc(n * sizeof(int));    \n    for ( i = 0; i &lt; n; i++ ) scanf( \"%d\", &amp;mas[i] );    \n    scanf( \"%d\", &amp;target );    \n    printf(\"%d\\n\", BinarySearch(mas,n,target ) );    \n    return 0;\n}\n\nint BinarySearch( int *mas, int n, int target ) \n{    \n    int start = 0, finish = n-1, middle;    \n    while ( start &lt;= finish ) \n    {       \n        middle = ( start + finish ) / 2;        \n		switch ( compare(mas[middle],target) ) \n        {            \n            case -1: start = middle + 1; break;            \n            case 0: return middle;            \n            case 1: finish = middle - 1; break;        \n        }    \n    }    \n    return -1;\n}\n\nint compare ( int x, int y ) \n{    \n    if ( x &lt; y ) return -1;    \n    if ( x == y ) return 0;    \n    return 1;\n}\n</pre>\n\n<p>Реализация двоичного поиска на С++:</p>\n\n<pre class=\"brush: cpp;\">\n#include &lt;iostream&gt;\nusing namespace std;\n\nint BinarySearch( int*, int, int );\nint compare ( int , int );\n\nint main() \n{    \n    int *mas, n, i, target;    \n    cin &gt;&gt; n;    \n    mas = new int[n];    \n    for ( i = 0; i &lt; n; i++ ) cin &gt;&gt; mas[i];    \n    cin &gt;&gt; target;   \n    cout &lt;&lt; BinarySearch(mas,n,target) &lt;&lt; endl;    \n    return 0;\n}\n\nint BinarySearch( int *mas, int n, int target ) \n{    \n    int start = 0, finish = n-1, middle;    \n    while ( start &lt;= finish ) \n    {        \n        middle = ( start + finish ) / 2;       \n        switch ( compare(mas[middle],target) ) \n        {            \n            case -1: start = middle + 1; break;            \n            case 0: return middle;            \n            case 1: finish = middle - 1; break;        \n        }    \n    }    \n    return -1;\n}\n\nint compare ( int x, int y ) \n{    \n    if ( x &lt; y ) return -1;    \n    if ( x == y ) return 0;    \n    return 1;\n}\n</pre>\n\n<p>Реализация двоичного поиска на Java:</p>\n\n<pre class=\"brush: java;\">\nimport java.io.*;\nimport java.util.*;\n\nclass BinarySearch \n{     \n    public static void main(String[] args) \n    {          \n        Locale.setDefault(Locale.ENGLISH);\n        Scanner in = new Scanner(System.in);        \n        PrintWriter out = new PrintWriter(System.out);          \n        int mas[], n, i, target;        \n        n = in.nextInt();        \n        mas = new int[n];       \n        for ( i = 0; i &lt; n; i++ ) mas[i] = in.nextInt();        \n        target = in.nextInt();        \n        out.println( BinarySearch(mas,n,target) );        \n        out.flush();   \n    }   \n    public static int BinarySearch( int mas[], int n, int target ) \n    {	    \n        int start = 0, finish = n-1, middle;        \n        while ( start &lt;= finish ) \n        {            \n            middle = ( start + finish ) / 2;            \n            switch ( compare(mas[middle],target) ) \n            {                \n                case -1: start = middle + 1; break;                \n                case 0: return middle;                \n                case 1: finish = middle - 1; break;            \n            }        \n        }        \n        return -1;    \n    }    \n    public static int compare ( int x, int y ) \n    {        \n        if ( x &lt; y ) return -1;        \n        if ( x == y ) return 0;        \n        return 1;    \n    }\n}\n</pre>\n\n<p>Лекцию подготовили: <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a> и <a href=\"[[constant name=portal_url]]users/show/?id=2\">Александр Проскуряков</a></p>\n\n<p>Реализации: С/С++/Java - <a href=\"[[constant name=portal_url]]users/show/?id=1\">Али Велиев</a></p>\n\n<p>Pascal - <a href=\"[[constant name=portal_url]]users/show/?id=3\">Сабина Исаева</a></p>\n', '2014-08-16 14:13:28', 0, 1, 1),
(41, 'ru', 'Введение и основные понятия в теории графов', 110, 'введение-и-основные-понятия-в-теории-графов', '<p>В интернете существует огромное количество книг по теории графов. И если взять их общее пересечение, к нему дописать все вытекающие последствия, то можно создать огромный том, прочитав который останется ещё куча вопросов. Поэтому представляем Вам вырезку из небольшой книжки по \"Теории графов\". Мы редко будем выкладывать лекции на эту тему собственного авторства, так как не видим в этом никакого смысла. Ведь всё что мы хотим донести Вам, уважаемые читатели, уже другими словами описано во многих книгах. Для решения задач на эту тему изначально надо знать достаточное количество определений и свойств, а после мы перейдём к изучению самих алгоритмов. Знание свойств графов не менее важно, так как иногда попадаются задачи, где просто надо воспользоваться формулой, а не обходить граф в глубину или вообще сохранять его как-то в памяти.</p>\n', '<p>В интернете существует огромное количество книг по теории графов. И если взять их общее пересечение, к нему дописать все вытекающие последствия, то можно создать огромный том, прочитав который останется ещё куча вопросов. Поэтому представляем Вам вырезку из небольшой книжки по \"Теории графов\". Мы редко будем выкладывать лекции на эту тему собственного авторства, так как не видим в этом никакого смысла. Ведь всё что мы хотим донести Вам, уважаемые читатели, уже другими словами описано во многих книгах. Для решения задач на эту тему изначально надо знать достаточное количество определений и свойств, а после мы перейдём к изучению самих алгоритмов. Знание свойств графов не менее важно, так как иногда попадаются задачи, где просто надо воспользоваться формулой, а не обходить граф в глубину или вообще сохранять его как-то в памяти.</p>\n\n\n<p>Мы не будем останавливаться на каких-то конкретных лекциях, поскольку, как уже было сказано выше, в большинстве случаев это одна и та же мысль, написанная на разных языках. И чтобы читатель не привык к одному и тому же стилю изложения, мы будем выкладывать лекции из разных источников. Однако мы будем стараться их строить так, чтобы эта разница никак не показывала себя.</p>\n\n<h3>Немного истории и о предмете...</h3>\n\n<p>Теория графов является одним из разделов дискретной математики, который исследует свойства конечных или счетных множеств с заданными отношениями между их элементами. Особенностью этой теории является геометрический подход к изучению объектов.</p>\n\n<p>Впервые понятие «граф» ввел в 1936 году венгерский математик Денеш Кëниг. Однако первая работа по теории графов была написана еще в 1736 году Леонардом Эйлером, в которой он решил «задачу о Кëнигсбергских мостах». Суть этой задачи состоит в следующем. На рис. 1 представлена схема центральной части города Кëнигсберг (ныне Калининград), которая включает два берега реки, два острова в ней и семь соединяющих их мостов. Требуется обойти все четыре части суши, пройдя по каждому мосту один раз, и вернуться в исходную точку. Позже мы рассмотрим решение этой задачи.</p>\n\n<p align=\"center\"><img src=\"/images/algo/5_1.png\" /></p>\n\n<p>Современная теория графов даёт исключительно удобный аппарат для моделирования структурных свойств различных систем и отношений между объектами разной природы. Поэтому она широко используется как в самой математике, так и ее приложениях в самых разнообразных областях науки, техники и практической деятельности. В частности, теория графов находит свое применение в информатике и программировании, химии, экономике, логистике, в коммуникационных и транспортных системах, схемотехнике.</p>\n\n<h3>Основные понятия и определения</h3>\n\n<p>Пусть S &nbsp;– &nbsp;непустое &nbsp;конечное &nbsp;множество, &nbsp; V(2) &nbsp;– &nbsp;множество &nbsp; всех &nbsp;его двухэлементных&nbsp;подмножеств.</p>\n\n<p><em><strong>Определение &nbsp;1.1.</strong></em> &nbsp;Псевдографом &nbsp;(или просто графом) G &nbsp;называется &nbsp;пара множеств (S,U), где U -&nbsp;произвольное&nbsp;подмножество множества V(2) . При этом пишут G = (S,U).</p>\n\n<p><em><strong>Определение &nbsp;1.2.</strong></em> &nbsp;Пусть G &nbsp;= &nbsp;(S,U) &nbsp;– &nbsp;псевдограф. &nbsp;Элементы &nbsp;множества &nbsp;S называются вершинами&nbsp;графа G, а элементы множества &nbsp;U – его ребрами.&nbsp;</p>\n\n<p><em><strong>Определение 1.3.</strong></em> Граф G = (S,U) называется пустым&nbsp;или нуль-графом, если&nbsp;U = ∅.</p>\n\n<p><em><strong>Определение 1.4.</strong></em> Число вершин графа G = (S,U) называется его порядком.&nbsp;Если порядок графа равен n, то пишут |G| = n.</p>\n\n<p>Двухэлементное подмножество &nbsp;множества S (ребро), &nbsp;принадлежащее U и&nbsp;состоящее из элементов x и y будем&nbsp;обозначать через (x, y).&nbsp;В общем случае множество U может содержать пары с одинаковыми элементами вида (x, x) и одинаковые&nbsp;пары.</p>\n\n<p><em><strong>Определение 1.5.</strong></em> Ребра вида (x, x) называются петлями.</p>\n\n<p><em><strong>Определение 1.6.</strong></em> Одинаковые пары из множества U называются кратными&nbsp;(или параллельными) ребрами.</p>\n\n<p>Таким образом, псевдограф может содержать петли и кратные ребра. В этом смысле псевдографы еще&nbsp;называются графами с кратными ребрами и петлями.</p>\n\n<p><em><strong>Определение &nbsp;1.7.</strong></em> &nbsp;Псевдограф &nbsp;без &nbsp;петель &nbsp;называется &nbsp;мультиграфом &nbsp;(или графом с кратными&nbsp;ребрами).</p>\n\n<p><em><strong>Определение &nbsp; 1.8.</strong></em> &nbsp; Мультиграф &nbsp; без &nbsp;кратных &nbsp; ребер &nbsp;называется &nbsp;простым&nbsp;графом.</p>\n\n<p>Таким образом, простой граф не содержит петель и кратных ребер.</p>\n\n<p>Графы имеют наглядную &nbsp;графическую &nbsp;интерпретацию в виде диаграмм, состоящих из точек и линий,&nbsp;соединяющих &nbsp;некоторые из этих точек. Точки соответствуют вершинам графа, а линии &nbsp;– его ребрам.&nbsp;При этом форма и длина линий значения не имеют. Важно лишь, что две данные точки соединены или не&nbsp;соединены линией.</p>\n\n<p><span style=\"line-height:1.6em\"><em><strong>Пример 1.1.</strong></em> Указать какие из графов, диаграммы которых изображены на&nbsp;</span><span style=\"line-height:1.6em\">рис. 2 являются псевдографами, мультиграфами, простыми графами.</span></p>\n\n<p align=\"center\"><img src=\"/images/algo/5_2.png\" /></p>\n\n<p><em><strong>Решение.</strong></em> &nbsp; Все &nbsp;графы &nbsp; являются псевдографами, &nbsp; графы &nbsp; G1, &nbsp;G3, &nbsp;G4, &nbsp;G5 –&nbsp;мультиграфами, графы G1, G4, G5 &nbsp;-&nbsp;простыми графами. &nbsp;</p>\n\n<p><em><strong>Определение 1.9. </strong></em>&nbsp; &nbsp;Граф называется <strong>неориентированным</strong> (кратко &nbsp;–&nbsp;неорграфом), если пары в множестве U являются неупорядоченными.</p>\n\n<p>Если &nbsp;(x, y) &nbsp; – &nbsp; неупорядоченная &nbsp; пара, &nbsp; то &nbsp;ребро (x, y) называется&nbsp;неориентированным, а вершины x &nbsp;и y называются&nbsp;концами&nbsp;неориентированного ребра (x, y).</p>\n\n<p><em><strong>Определение 1.10.</strong></em> Граф называется <strong>ориентированным</strong> (кратко – орграфом),&nbsp;если пары в множестве U являются упорядоченными.</p>\n\n<p><em><strong>Определение 1.11.</strong></em>&nbsp;Ребра орграфа называются <strong>дугами</strong> (или&nbsp;ориентированными ребрами).</p>\n\n<p>Вершина x дуги (x, y) называется ее началом, &nbsp;а вершина y – ее концом. В&nbsp;этом случае говорят, что дуга (x, y) исходит из вершины x и входит в вершину y.&nbsp;На диаграммах орграфов направления дуг отмечаются стрелками, которые примыкают к их концам.</p>\n\n<p><em><strong>Замечание 1.1.</strong></em> Неориентированное ребро (x, y) равносильно двум&nbsp;противоположно направленным дугам (x, y) и (y, x). Поэтому неориентированный граф можно&nbsp;рассматривать как ориентированный граф, который вместе с каждой дугой (x, y) содержит и дугу (y, x)&nbsp;противоположного направления.</p>\n\n<p>Условимся вершины графа обозначать буквами x, y, z (без индексов или с индексами), а ребра и дуги –&nbsp;буквами v, u, w (без индексов или с индексами).&nbsp;Рассмотрим ряд понятий и определений для неориентированных &nbsp;и&nbsp;ориентированных графов. &nbsp;При этом, если не будет оговорено особо, те же понятия и определения&nbsp;переносятся без изменений на неориентированные &nbsp;и ориентированные псевдографы.</p>\n\n<p><em><strong>Определение 1.12.</strong></em> Два ребра графа называются <strong>смежными</strong>, если они имеют общий конец.</p>\n\n<p><em><strong>Определение 1.13.</strong></em> Вершина x и ребро u графа называются <strong>инцидентными</strong>,&nbsp;если x является концом ребра u, и неинцидентными в противном случае.</p>\n\n<p><em><strong>Определение 1.14.</strong></em> Две вершины графа называются <strong>смежными</strong>, если существует инцидентное им ребро.</p>\n\n<p><em><strong>Определение 1.15.</strong></em> Число ребер (дуг) графа (орграфа) G, инцидентных данной вершине x<sub>i</sub> называется&nbsp;<strong>степенью (валентностью) вершины</strong> x<sub>i</sub> и обозначается через deg (x<sub>i</sub>) (от англ. degree – степень).</p>\n\n<p><em><strong>Определение 1.16.</strong></em> Вершина графа называется <strong>изолированной</strong>, &nbsp;если ее степень&nbsp;равна нулю.</p>\n\n<p><em><strong>Определение 1.17.</strong></em> Вершина графа называется <strong>висячей</strong>, &nbsp;а если ее степень равна единице.</p>\n\n<p><em><strong>Замечание 1.2.</strong></em> В случае неориентированного псевдографа обычно считается, что вклад каждой петли,&nbsp;инцидентной некоторой вершине x, в ее степень P(x) равен 2, в то время как вклад любого другого&nbsp;ребра, инцидентного вершине x равен 1.</p>\n\n<p><em><strong>Определение 1.18.</strong></em> Полустепенью исхода (захода) вершины xi орграфа называется число deg<sup>+</sup>(x<sub>i</sub>) (deg<sup>–</sup>(x<sub>i</sub>)) его дуг, исходящих из вершины x<sub>i</sub> (заходящих в вершину x<sub>i</sub>).&nbsp;Для орграфа deg (x<sub>i</sub>) = deg<sup>+</sup>(x<sub>i</sub>) + deg<sup>–</sup>(x<sub>i</sub>).</p>\n\n<p><em><strong>Замечание 1.3.</strong></em> В случае ориентированного псевдографа вклад каждой петли,&nbsp;инцидентной некоторой вершине x, равен 1, как в deg<sup>+</sup>(x), так и в deg<sup>–</sup>(x).</p>\n\n<p><em><strong>Определение 1.19.</strong></em> Неориентированный простой граф, &nbsp;в котором любые две&nbsp;различные &nbsp;вершины &nbsp;смежны, называется&nbsp;<strong>полным</strong>. Полный граф &nbsp;порядка &nbsp;n&nbsp;обозначается через K<sub>n</sub>.</p>\n\n<p><em><strong>Определение &nbsp;1.20.</strong></em> &nbsp;Неориентированный &nbsp;граф &nbsp;называется &nbsp;<strong>двудольным</strong>, если&nbsp;существует такое разбиение множества его вершин &nbsp;на две части (доли), что концы каждого ребра&nbsp;принадлежат разным частям.</p>\n\n<p><em><strong>Определение 1.21.</strong></em> &nbsp;Двудольный граф, любые две вершины которого, входящие&nbsp;в разные доли смежны, &nbsp;называется <strong>полным двудольным</strong>. Полный двудольный граф, доли которого состоят&nbsp;из p и q вершин, обозначается символом K<sub>p,q</sub>.</p>\n\n<p>Источник: А.В. Чередникова, И.В. Землякова, Введение в теорию графов, Кострома, КГТУ, 2011</p>\n', '2014-08-16 14:15:11', 0, 1, 1),
(42, 'en', 'What should you know about algorithms? ', 108, 'what-should-you-know-about-algorithms', '<p>The Programmers are very demanded in contemporary world. But what does this word mean? Is it a man who writes meaningless machine code all days long? And why do you think that it is meaningless? Maybe something hidden behind it? &nbsp;This profession is one of the hardest and demands the algorithmic thinking.</p>\n', '<p>The Programmers are very demanded in contemporary world. But what does this word mean? Is it a man who writes meaningless machine code all days long? And why do you think that it is meaningless? Maybe something hidden behind it? &nbsp;This profession is one of the hardest and demands the algorithmic thinking.</p>\n\n<p>But what is the algorithm?</p>\n\n<p>The answer to this question we can find in Wikipedia;</p>\n\n<blockquote>\n<p>Algorithm is finite lists of instructions for getting the result of problems.</p>\n</blockquote>\n\n<p>There is no need to read all this article elaborately to get that programmer must be able to understand and manipulate with algorithms. In out web-site we have “Coding” tab. Mainly this tab will be useful for coders. Coders are the people who are implementing complete algorithms. Our resource is useful both for algorithmers and coders.</p>\n\n<p>And now let’s look at the process of composing algorithms.</p>\n\n<ol>\n	<li>Read the conditions attentively and try to understand it. Think about task’s input and output.</li>\n	<li>Draw the straight algorithm.</li>\n	<li>Try to optimize it. Algorithm must implement less operations and structures must use as less memory as it is possible.</li>\n	<li>After getting the algorithm that will work under conditions that we have mentioned it’s time to implement it. Try to divide the algorithm into the maximum possible parts(functions and procedures). And then make their superposition.</li>\n	<li>Implement each function as individual program. Carefully check them.</li>\n</ol>\n\n<p>As you see using these rules will help you to implement invented algorithm correctly.&nbsp;</p>\n\n<p>And if something goes wrong you know where to go.</p>\n\n<p>Ask your questions in website of intellectual club “<a href=\"http://qformat.net/blog/ocode/\">QFormat</a>” and also in our <a href=\"http://www.facebook.com/groups/studyprog/\">FB group</a>. See you, dear STUDYPROGrammers.&nbsp;</p>\n', '2014-07-04 03:28:43', 0, 1, 1),
